t["I keep wondering which choice might have brought %1 home."] = "\\u0644\\u0633\\u0627 \\u0628\\u0633\\u0623\\u0644 \\u062D\\u0627\\u0644\\u064A \\u0623\\u064A \\u0642\\u0631\\u0627\\u0631 \\u0643\\u0627\\u0646 \\u0631\\u062C\\u0651\\u0639\\u0644\\u0646\\u0627 %1 \\u0639\\u0627\\u0644\\u0628\\u064A\\u062A."
