t["I knew there was something left. %1!"] = "\\u0643\\u0646\\u062A \\u0639\\u0627\\u0631\\u0641\\u0629 \\u0641\\u064A \\u0634\\u064A \\u0628\\u0627\\u0642\\u064A. %1!"
