t["I know %1 is gone. My mind hasn't caught up yet."] = "\\u0628\\u0639\\u0631\\u0641 \\u0625\\u0646\\u0647 %1 \\u0645\\u0627 \\u0639\\u0627\\u062F \\u0645\\u0639\\u0646\\u0627. \\u0628\\u0633 \\u0639\\u0642\\u0644\\u064A \\u0644\\u0633\\u0627 \\u0645\\u0648 \\u0645\\u0635\\u062F\\u0642."
