t["I know it hurts. Keep still for me."] = "\\u0628\\u0639\\u0631\\u0641 \\u0639\\u0645 \\u064A\\u0648\\u062C\\u0639\\u0643. \\u062B\\u0628\\u062A \\u0643\\u0631\\u0645\\u0627\\u0644\\u064A."
