t["I learned something from %1. I'm still deciding what to do with it."] = "\\u062A\\u0639\\u0644\\u0645\\u062A \\u0634\\u064A \\u0645\\u0646 %1. \\u0644\\u0633\\u0627 \\u0639\\u0645 \\u0642\\u0631\\u0631 \\u0634\\u0648 \\u0627\\u0639\\u0645\\u0644 \\u0641\\u064A\\u0647."
