t["I lost one world and found a family in you. Thank you."] = "\\u062E\\u0633\\u0631\\u062A \\u062F\\u0646\\u064A\\u0627 \\u0648\\u0644\\u0642\\u064A\\u062A \\u0639\\u064A\\u0644\\u0629 \\u0641\\u064A\\u0643. \\u0634\\u0643\\u0631\\u0627."
