t["I love that I got to know you before I forgot everything."] = "\\u0628\\u062D\\u0628 \\u0625\\u0646\\u064A \\u0644\\u062D\\u0642\\u062A \\u0627\\u0639\\u0631\\u0641\\u0643 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0627\\u0646\\u0633\\u0649 \\u0643\\u0644 \\u0634\\u064A."
t["I made it. Please do not copy that landing."] = "\\u0648\\u0635\\u0644\\u062A. \\u0627\\u0644\\u0644\\u0647 \\u064A\\u062E\\u0644\\u064A\\u0643 \\u0644\\u0627 \\u062A\\u0642\\u0644\\u062F \\u0647\\u0627\\u0644\\u0646\\u0632\\u0644\\u0629."
