t["I might read %1 aloud if anyone wants to listen."] = "\\u064A\\u0645\\u0643\\u0646 \\u0627\\u0642\\u0631\\u0627 %1 \\u0628\\u0635\\u0648\\u062A \\u0639\\u0627\\u0644\\u064A \\u0625\\u0630\\u0627 \\u062D\\u062F\\u0627 \\u0628\\u062F\\u0648 \\u064A\\u0633\\u0645\\u0639."
