t["I miss libraries. Mostly I miss choosing what to worry about."] = "\\u0627\\u0634\\u062A\\u0642\\u062A \\u0644\\u0644\\u0645\\u0643\\u062A\\u0628\\u0627\\u062A. \\u0648\\u0623\\u0643\\u062A\\u0631 \\u0634\\u064A \\u0627\\u0634\\u062A\\u0642\\u062A \\u0627\\u062E\\u062A\\u0627\\u0631 \\u0634\\u0648 \\u064A\\u0634\\u063A\\u0644 \\u0628\\u0627\\u0644\\u064A."
t["I miss seeing people sit out on their porches."] = "\\u0627\\u0634\\u062A\\u0642\\u062A \\u0634\\u0648\\u0641 \\u0627\\u0644\\u0646\\u0627\\u0633 \\u0642\\u0627\\u0639\\u062F\\u0629 \\u0639\\u0627\\u0644\\u0628\\u0631\\u0646\\u062F\\u0627\\u062A."
t["I miss terrible television. There, no zombies in that sentence."] = "\\u0645\\u0634\\u062A\\u0627\\u0642\\u0629 \\u0644\\u0644\\u062A\\u0644\\u0641\\u0632\\u064A\\u0648\\u0646 \\u0627\\u0644\\u0632\\u0628\\u0627\\u0644\\u0629. \\u064A\\u0644\\u0627\\u060C \\u0648\\u0644\\u0627 \\u0632\\u0648\\u0645\\u0628\\u064A \\u0628\\u0647\\u0627\\u0644\\u062C\\u0645\\u0644\\u0629."
t["I miss that too. A warm room and nowhere urgent to be."] = "\\u0648\\u0623\\u0646\\u0627 \\u0643\\u0645\\u0627\\u0646 \\u0627\\u0634\\u062A\\u0642\\u062A. \\u0623\\u0648\\u0636\\u0629 \\u062F\\u0627\\u0641\\u064A\\u0629 \\u0648\\u0645\\u0627 \\u0641\\u064A \\u0634\\u064A \\u0645\\u0633\\u062A\\u0639\\u062C\\u0644."
t["I miss the ordinary annoyance of an advertisement."] = "\\u0627\\u0634\\u062A\\u0642\\u062A \\u0644\\u0646\\u0643\\u062F \\u0627\\u0644\\u0625\\u0639\\u0644\\u0627\\u0646\\u0627\\u062A \\u0627\\u0644\\u0639\\u0627\\u062F\\u064A."
t["I miss the smell of cut hay more than I expected."] = "\\u0627\\u0634\\u062A\\u0642\\u062A \\u0644\\u0631\\u064A\\u062D\\u0629 \\u0627\\u0644\\u0642\\u0634 \\u0627\\u0644\\u062C\\u062F\\u064A\\u062F \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0627 \\u062A\\u0648\\u0642\\u0639\\u062A."
t["I need %2 before trying %1 again. That last attempt failed."] = "\\u0628\\u062F\\u064A %2 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062C\\u0631\\u0628 %1 \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629. \\u0622\\u062E\\u0631 \\u0645\\u062D\\u0627\\u0648\\u0644\\u0629 \\u0645\\u0627 \\u0632\\u0628\\u0637\\u062A."
t["I need a better setup before I try that."] = "\\u0628\\u062F\\u064A \\u062A\\u0631\\u062A\\u064A\\u0628 \\u0623\\u062D\\u0633\\u0646 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062C\\u0631\\u0628."
t["I need a blade before this turns into supper."] = "\\u0628\\u062F\\u064A \\u0634\\u0641\\u0631\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0635\\u064A\\u0631 \\u0647\\u0627\\u062F \\u0639\\u0634\\u0627."
t["I need a break before I can do anything else."] = "\\u0628\\u062F\\u064A \\u0627\\u0633\\u062A\\u0631\\u0627\\u062D\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0627\\u0639\\u0645\\u0644 \\u0623\\u064A \\u0634\\u064A."
t["I need a breath. I don't want to become your problem."] = "\\u0628\\u062F\\u064A \\u0646\\u0641\\u0633. \\u0645\\u0627 \\u0628\\u062F\\u064A \\u0635\\u064A\\u0631 \\u0645\\u0634\\u0643\\u0644\\u062A\\u0643."
t["I need a cigarette. Badly."] = "\\u0628\\u062F\\u064A \\u0633\\u064A\\u062C\\u0627\\u0631\\u0629. \\u0636\\u0631\\u0648\\u0631\\u064A."
t["I need a clean start, even if it's only for tonight."] = "\\u0628\\u062F\\u064A \\u0628\\u062F\\u0627\\u064A\\u0629 \\u0646\\u0636\\u064A\\u0641\\u0629\\u060C \\u0644\\u0648 \\u0644\\u0644\\u064A\\u0644\\u0629 \\u0648\\u062D\\u062F\\u0629 \\u0628\\u0633."
t["I need a clear moment to continue %1."] = "\\u0628\\u062F\\u064A \\u0644\\u062D\\u0638\\u0629 \\u0635\\u0627\\u0641\\u064A\\u0629 \\u0644\\u0643\\u0641\\u0651\\u064A %1."
t["I need a cooking pot to get this meal started."] = "\\u0628\\u062F\\u064A \\u0637\\u0646\\u062C\\u0631\\u0629 \\u0644\\u0628\\u0644\\u0651\\u0634 \\u0628\\u0647\\u0627\\u0644\\u0637\\u0628\\u062E\\u0629."
t["I need a drink before too long."] = "\\u0628\\u062F\\u064A \\u0627\\u0634\\u0631\\u0628 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0637\\u0648\\u0644 \\u0627\\u0644\\u0648\\u0642\\u062A."
t["I need a drink soon."] = "\\u0628\\u062F\\u064A \\u0627\\u0634\\u0631\\u0628 \\u0642\\u0631\\u064A\\u0628\\u0627\\u064B."
t["I need a drink soon. Does everyone else have water?"] = "\\u0628\\u062F\\u064A \\u0627\\u0634\\u0631\\u0628 \\u0642\\u0631\\u064A\\u0628\\u0627\\u064B. \\u0627\\u0644\\u0643\\u0644 \\u0645\\u0639\\u0647 \\u0645\\u064A\\u061F"
t["I need a drink while I can still think clearly."] = "\\u0628\\u062F\\u064A \\u0627\\u0634\\u0631\\u0628 \\u0637\\u0627\\u0644\\u0645\\u0627 \\u0644\\u0633\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0641\\u0643\\u0631 \\u0635\\u062D."
t["I need a favor. A big one. Don't say anything yet."] = "\\u0628\\u062F\\u064A \\u0645\\u0646\\u0643 \\u062E\\u062F\\u0645\\u0629. \\u0643\\u0628\\u064A\\u0631\\u0629. \\u0644\\u0627 \\u062A\\u0642\\u0648\\u0644 \\u0634\\u064A \\u0644\\u0633\\u0627."
t["I need a few quiet minutes."] = "\\u0628\\u062F\\u064A \\u0643\\u0645 \\u062F\\u0642\\u064A\\u0642\\u0629 \\u0647\\u062F\\u0648\\u0621."
t["I need a fishing rod before I can catch anything."] = "\\u0628\\u062F\\u064A \\u0635\\u0646\\u0627\\u0631\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0627\\u0635\\u0637\\u0627\\u062F \\u0634\\u064A."
t["I need a frying pan for this meal."] = "\\u0628\\u062F\\u064A \\u0645\\u0642\\u0644\\u0627\\u064A\\u0629 \\u0644\\u0647\\u0627\\u0644\\u0623\\u0643\\u0644\\u0629."
t["I need a fueled blowtorch for this metalwork."] = "\\u0628\\u062F\\u064A \\u0634\\u0627\\u0644\\u064A\\u0645\\u0648 \\u0645\\u0639\\u0628\\u0651\\u0649 \\u0644\\u0647\\u0627\\u0644\\u0634\\u063A\\u0644 \\u0628\\u0627\\u0644\\u062D\\u062F\\u064A\\u062F."
t["I need a fueled blowtorch."] = "\\u0628\\u062F\\u064A \\u0634\\u0627\\u0644\\u064A\\u0645\\u0648 \\u0645\\u0639\\u0628\\u0651\\u0649."
t["I need a hammer before I can finish the carpentry."] = "\\u0628\\u062F\\u064A \\u0634\\u0627\\u0643\\u0648\\u0634 \\u0644\\u062E\\u0644\\u0651\\u0635 \\u0627\\u0644\\u0646\\u062C\\u0627\\u0631\\u0629."
t["I need a hammer that is still on speaking terms with its handle."] = "\\u0628\\u062F\\u064A \\u0634\\u0627\\u0643\\u0648\\u0634 \\u0644\\u0633\\u0627 \\u0631\\u0627\\u0633\\u0647 \\u0645\\u0648 \\u0632\\u0639\\u0644\\u0627\\u0646 \\u0645\\u0646 \\u0625\\u064A\\u062F\\u0647."
t["I need a hand over here!"] = "\\u0628\\u062F\\u064A \\u0625\\u064A\\u062F \\u0647\\u0648\\u0646!"
t["I need a plank before I can patch this gap."] = "\\u0628\\u062F\\u064A \\u0644\\u0648\\u062D \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0633\\u062F\\u0651 \\u0647\\u0627\\u0644\\u0641\\u062A\\u062D\\u0629."
t["I need a plank."] = "\\u0628\\u062F\\u064A \\u0644\\u0648\\u062D \\u062E\\u0634\\u0628."
t["I need a proper pry tool before this barricade comes loose."] = "\\u0628\\u062F\\u064A \\u0639\\u062F\\u0629 \\u062E\\u0644\\u0639 \\u0639\\u062F\\u0644\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0646\\u0641\\u0643 \\u0647\\u0627\\u0644\\u062D\\u0627\\u062C\\u0632."
t["I need a pry tool to get those boards off."] = "\\u0628\\u062F\\u064A \\u0639\\u062A\\u0644\\u0629 \\u0644\\u0634\\u064A\\u0644 \\u0647\\u0627\\u0644\\u0623\\u0644\\u0648\\u0627\\u062D."
t["I need a prying tool. My fingers have declined the assignment."] = "\\u0628\\u062F\\u064A \\u0639\\u062F\\u0629 \\u062E\\u0644\\u0639. \\u0623\\u0635\\u0627\\u0628\\u064A\\u0639\\u064A \\u0627\\u0639\\u062A\\u0630\\u0631\\u062A \\u0639\\u0646 \\u0647\\u0627\\u0644\\u0645\\u0647\\u0645\\u0629."
t["I need a quiet minute somewhere safe."] = "\\u0628\\u062F\\u064A \\u062F\\u0642\\u064A\\u0642\\u0629 \\u0647\\u062F\\u0648\\u0621 \\u0628\\u0634\\u064A \\u0645\\u062D\\u0644 \\u0622\\u0645\\u0646."
t["I need a room, a door, and five minutes of silence."] = "\\u0628\\u062F\\u064A \\u063A\\u0631\\u0641\\u0629 \\u0648\\u0628\\u0627\\u0628 \\u0648\\u062E\\u0645\\u0633 \\u062F\\u0642\\u0627\\u064A\\u0642 \\u0633\\u0643\\u0648\\u062A."
t["I need a saw with teeth. A surprisingly strict requirement."] = "\\u0628\\u062F\\u064A \\u0645\\u0646\\u0634\\u0627\\u0631 \\u0625\\u0644\\u0647 \\u0623\\u0633\\u0646\\u0627\\u0646. \\u0634\\u0631\\u0637 \\u0635\\u0639\\u0628\\u060C \\u0645\\u064A\\u0646 \\u0643\\u0627\\u0646 \\u064A\\u062A\\u0648\\u0642\\u0639."
t["I need a screwdriver to finish this without wrecking it."] = "\\u0628\\u062F\\u064A \\u0645\\u0641\\u0643 \\u0644\\u062E\\u0644\\u0651\\u0635 \\u0647\\u0627\\u062F \\u0628\\u0644\\u0627 \\u0645\\u0627 \\u062E\\u0631\\u0651\\u0628\\u0647."
t["I need a screwdriver to take this apart."] = "\\u0628\\u062F\\u064A \\u0645\\u0641\\u0643 \\u0644\\u0641\\u0643\\u0651 \\u0647\\u0627\\u062F."
t["I need a second. I cannot get my breathing right."] = "\\u0628\\u062F\\u064A \\u0644\\u062D\\u0638\\u0629. \\u0645\\u0648 \\u0639\\u0645 \\u064A\\u0638\\u0628\\u0637 \\u0646\\u0641\\u0633\\u064A."
t["I need a sharp knife before I can prep this meal."] = "\\u0628\\u062F\\u064A \\u0633\\u0643\\u064A\\u0646\\u0629 \\u062D\\u0627\\u062F\\u0629 \\u0644\\u062C\\u0647\\u0651\\u0632 \\u0647\\u0627\\u0644\\u0623\\u0643\\u0644."
t["I need a short job with a clear finish."] = "\\u0628\\u062F\\u064A \\u0634\\u063A\\u0644\\u0629 \\u0642\\u0635\\u064A\\u0631\\u0629 \\u0625\\u0644\\u0647\\u0627 \\u0646\\u0647\\u0627\\u064A\\u0629 \\u0648\\u0627\\u0636\\u062D\\u0629."
t["I need a short reset. I'll come back when my head is clear."] = "\\u0628\\u062F\\u064A \\u0627\\u0633\\u062A\\u0631\\u0627\\u062D\\u0629 \\u0642\\u0635\\u064A\\u0631\\u0629. \\u0628\\u0631\\u062C\\u0639 \\u0644\\u0645\\u0627 \\u064A\\u0631\\u0648\\u0642 \\u0631\\u0627\\u0633\\u064A."
t["I need a short stop. Keep an ear out."] = "\\u0628\\u062F\\u064A \\u0648\\u0642\\u0641\\u0629 \\u0642\\u0635\\u064A\\u0631\\u0629. \\u062E\\u0644\\u064A \\u0623\\u062F\\u0646\\u0643 \\u0645\\u0641\\u062A\\u0648\\u062D\\u0629."
t["I need a shovel before I can open that grave."] = "\\u0628\\u062F\\u064A \\u0643\\u0631\\u064A\\u0643 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0627\\u0641\\u062A\\u062D \\u0647\\u0627\\u0644\\u0642\\u0628\\u0631."
t["I need a sleep cycle before the next demanding job."] = "\\u0628\\u062F\\u064A \\u0646\\u0648\\u0645\\u0629 \\u0643\\u0627\\u0645\\u0644\\u0629 \\u0642\\u0628\\u0644 \\u0627\\u0644\\u0634\\u063A\\u0644\\u0629 \\u0627\\u0644\\u0635\\u0639\\u0628\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629."
t["I need a sound digging tool, not the first rusty thing we find."] = "\\u0628\\u062F\\u064A \\u0639\\u062F\\u0629 \\u062D\\u0641\\u0631 \\u0633\\u0644\\u064A\\u0645\\u0629\\u060C \\u0645\\u0648 \\u0623\\u0648\\u0644 \\u062E\\u0631\\u062F\\u0629 \\u0646\\u0644\\u0627\\u0642\\u064A\\u0647\\u0627."
t["I need a tool that can remove barricades."] = "\\u0628\\u062F\\u064A \\u0639\\u062F\\u0629 \\u0628\\u062A\\u0634\\u064A\\u0644 \\u0627\\u0644\\u062D\\u0648\\u0627\\u062C\\u0632."
t["I need a usable hammer before this turns into an apology."] = "\\u0628\\u062F\\u064A \\u0634\\u0627\\u0643\\u0648\\u0634 \\u0645\\u0646\\u064A\\u062D \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0635\\u064A\\u0631 \\u0627\\u0644\\u0634\\u063A\\u0644 \\u0641\\u0636\\u064A\\u062D\\u0629."
t["I need a weapon before I take this on."] = "\\u0628\\u062F\\u064A \\u0633\\u0644\\u0627\\u062D \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0627\\u0648\\u0627\\u062C\\u0647 \\u0647\\u0627\\u062F."
t["I need a working blowtorch with fuel. An empty one is decoration."] = "\\u0628\\u062F\\u064A \\u0634\\u0627\\u0644\\u064A\\u0645\\u0648 \\u0634\\u063A\\u0651\\u0627\\u0644 \\u0648\\u0645\\u0639\\u0628\\u0651\\u0649. \\u0627\\u0644\\u0641\\u0627\\u0636\\u064A \\u0645\\u062C\\u0631\\u062F \\u062F\\u064A\\u0643\\u0648\\u0631."
t["I need a working saw. This wood won't cut itself."] = "\\u0628\\u062F\\u064A \\u0645\\u0646\\u0634\\u0627\\u0631 \\u0634\\u063A\\u0651\\u0627\\u0644. \\u0627\\u0644\\u062E\\u0634\\u0628 \\u0645\\u0627 \\u0631\\u062D \\u064A\\u0642\\u0635 \\u062D\\u0627\\u0644\\u0647."
t["I need a working screwdriver. Nothing dramatic. Just essential."] = "\\u0628\\u062F\\u064A \\u0645\\u0641\\u0643 \\u0634\\u063A\\u0651\\u0627\\u0644. \\u0645\\u0627 \\u0641\\u064A \\u062F\\u0631\\u0627\\u0645\\u0627. \\u0628\\u0633 \\u0636\\u0631\\u0648\\u0631\\u064A."
t["I need a working stove or a lit campfire for this."] = "\\u0628\\u062F\\u064A \\u063A\\u0627\\u0632 \\u0634\\u063A\\u0651\\u0627\\u0644 \\u0623\\u0648 \\u0646\\u0627\\u0631 \\u0645\\u0648\\u0642\\u062F\\u0629 \\u0644\\u0647\\u064A \\u0627\\u0644\\u0637\\u0628\\u062E\\u0629."
t["I need a working tool for this plot."] = "\\u0628\\u062F\\u064A \\u0639\\u062F\\u0629 \\u0634\\u063A\\u0651\\u0627\\u0644\\u0629 \\u0644\\u0647\\u0627\\u0644\\u0623\\u0631\\u0636."
t["I need an axe for chopping those trees you asked about."] = "\\u0628\\u062F\\u064A \\u0641\\u0627\\u0633 \\u0644\\u0623\\u0642\\u0637\\u0639 \\u0627\\u0644\\u0634\\u062C\\u0631 \\u0627\\u0644\\u0644\\u064A \\u0633\\u0623\\u0644\\u062A \\u0639\\u0646\\u0647."
t["I need an unbroken hammer."] = "\\u0628\\u062F\\u064A \\u0634\\u0627\\u0643\\u0648\\u0634 \\u0645\\u0648 \\u0645\\u0643\\u0633\\u0648\\u0631."
t["I need an unbroken saw."] = "\\u0628\\u062F\\u064A \\u0645\\u0646\\u0634\\u0627\\u0631 \\u0633\\u0644\\u064A\\u0645."
t["I need an unbroken screwdriver."] = "\\u0628\\u062F\\u064A \\u0645\\u0641\\u0643 \\u0633\\u0644\\u064A\\u0645."
t["I need another second. Keep breathing."] = "\\u0628\\u062F\\u064A \\u062B\\u0627\\u0646\\u064A\\u0629 \\u0643\\u0645\\u0627\\u0646. \\u0636\\u0644 \\u062A\\u0646\\u0641\\u0633."
t["I need bowls before I can serve this."] = "\\u0628\\u062F\\u064A \\u0632\\u0628\\u0627\\u062F\\u064A \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0642\\u062F\\u0651\\u0645 \\u0627\\u0644\\u0623\\u0643\\u0644."
t["I need calories before the next demanding job."] = "\\u0628\\u062F\\u064A \\u0634\\u064A \\u0628\\u064A\\u0642\\u0648\\u0651\\u064A\\u0646\\u064A \\u0642\\u0628\\u0644 \\u0627\\u0644\\u0634\\u063A\\u0644\\u0629 \\u0627\\u0644\\u0635\\u0639\\u0628\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629."
t["I need everyone to stay calm. I got bitten."] = "\\u0628\\u062F\\u064A \\u0627\\u0644\\u0643\\u0644 \\u064A\\u0647\\u062F\\u0649. \\u0623\\u0646\\u0627 \\u0627\\u0646\\u0639\\u0636\\u0651\\u064A\\u062A."
t["I need food before we move into any more danger."] = "\\u0628\\u062F\\u064A \\u0623\\u0643\\u0644 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0646\\u0641\\u0648\\u062A \\u0628\\u062E\\u0637\\u0631 \\u062A\\u0627\\u0646\\u064A."
t["I need food now."] = "\\u0628\\u062F\\u064A \\u0623\\u0643\\u0644 \\u0647\\u0644\\u0623."
t["I need food soon."] = "\\u0628\\u062F\\u064A \\u0623\\u0643\\u0644 \\u0642\\u0631\\u064A\\u0628\\u0627\\u064B."
t["I need food. I don't want anyone giving up their last meal for me."] = "\\u0628\\u062F\\u064A \\u0623\\u0643\\u0644. \\u0628\\u0633 \\u0645\\u0627 \\u0628\\u062F\\u064A \\u062D\\u062F\\u0627 \\u064A\\u0639\\u0637\\u064A\\u0646\\u064A \\u0622\\u062E\\u0631 \\u0644\\u0642\\u0645\\u0629 \\u0645\\u0639\\u0647."
t["I need fuel for the torch. Small detail. Quite important."] = "\\u0628\\u062F\\u064A \\u0648\\u0642\\u0648\\u062F \\u0644\\u0644\\u0634\\u0627\\u0644\\u064A\\u0645\\u0648. \\u062A\\u0641\\u0635\\u064A\\u0644 \\u0635\\u063A\\u064A\\u0631. \\u0645\\u0647\\u0645 \\u0634\\u0648\\u064A."
t["I need help before I can help anyone in there."] = "\\u0628\\u062F\\u064A \\u0645\\u064A\\u0646 \\u064A\\u0633\\u0627\\u0639\\u062F\\u0646\\u064A \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0633\\u0627\\u0639\\u062F \\u062D\\u062F\\u0627 \\u062C\\u0648\\u0627."
t["I need help finding somewhere safe to sleep."] = "\\u0628\\u062F\\u064A \\u0645\\u0633\\u0627\\u0639\\u062F\\u0629 \\u0644\\u0627\\u0642\\u064A \\u0645\\u062D\\u0644 \\u0622\\u0645\\u0646 \\u0646\\u0627\\u0645 \\u0641\\u064A\\u0647."
t["I need immediate rest before I become a liability."] = "\\u0628\\u062F\\u064A \\u0631\\u0627\\u062D\\u0629 \\u062D\\u0627\\u0644\\u0627\\u064B \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0635\\u064A\\u0631 \\u0639\\u0628\\u0621."
t["I need leverage before that barricade will move."] = "\\u0628\\u062F\\u064A \\u0634\\u064A \\u0628\\u064A\\u0631\\u0641\\u0639 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u062A\\u062D\\u0631\\u0643 \\u0647\\u0627\\u0644\\u062D\\u0627\\u062C\\u0632."
t["I need more room than this. Backing out."] = "\\u0628\\u062F\\u064A \\u0645\\u062C\\u0627\\u0644 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0647\\u064A\\u0643. \\u0637\\u0627\\u0644\\u0639\\u0629."
t["I need more rounds before the next serious fight."] = "\\u0628\\u062F\\u064A \\u0631\\u0635\\u0627\\u0635 \\u0632\\u064A\\u0627\\u062F\\u0629 \\u0642\\u0628\\u0644 \\u0627\\u0644\\u062E\\u0646\\u0627\\u0642\\u0629 \\u0627\\u0644\\u0643\\u0628\\u064A\\u0631\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629."
t["I need more time before I make that choice."] = "\\u0628\\u062F\\u064A \\u0648\\u0642\\u062A \\u0643\\u0645\\u0627\\u0646 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0627\\u062E\\u062A\\u0627\\u0631."
t["I need my last thought to be you getting away safely."] = "\\u0628\\u062F\\u064A \\u0622\\u062E\\u0631 \\u0641\\u0643\\u0631\\u0629 \\u0639\\u0646\\u062F\\u064A \\u062A\\u0643\\u0648\\u0646 \\u0625\\u0646\\u0643 \\u0641\\u0644\\u062A \\u0628\\u0623\\u0645\\u0627\\u0646."
t["I need one quiet corner, then I'll be ready again."] = "\\u0632\\u0627\\u0648\\u064A\\u0629 \\u0647\\u0627\\u062F\\u064A\\u0629 \\u0648\\u0628\\u0633\\u060C \\u0648\\u0628\\u0631\\u062C\\u0639 \\u062C\\u0627\\u0647\\u0632\\u0629."
t["I need quiet, not company. Please don't take it personally."] = "\\u0628\\u062F\\u064A \\u0647\\u062F\\u0648\\u0621\\u060C \\u0645\\u0648 \\u0648\\u0646\\u0633. \\u0644\\u0627 \\u062A\\u0627\\u062E\\u062F\\u0647\\u0627 \\u0639\\u0634\\u062E\\u0635\\u0643."
t["I need rest before I become another problem to solve."] = "\\u0628\\u062F\\u064A \\u0627\\u0631\\u062A\\u0627\\u062D \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0635\\u064A\\u0631 \\u0645\\u0634\\u0643\\u0644\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629 \\u0628\\u062F\\u0647\\u0627 \\u062D\\u0644."
t["I need rest. Someone else may have to take my watch."] = "\\u0628\\u062F\\u064A \\u0627\\u0631\\u062A\\u0627\\u062D. \\u064A\\u0645\\u0643\\u0646 \\u0644\\u0627\\u0632\\u0645 \\u062D\\u062F\\u0627 \\u062A\\u0627\\u0646\\u064A \\u064A\\u0627\\u062E\\u062F \\u0646\\u0648\\u0628\\u062A\\u064A."
t["I need room to finish this!"] = "\\u0628\\u062F\\u064A \\u0645\\u0637\\u0631\\u062D \\u0644\\u062E\\u0644\\u0635\\u0647!"
t["I need safe fluid before the next demanding job."] = "\\u0628\\u062F\\u064A \\u0634\\u064A \\u0646\\u0636\\u064A\\u0641 \\u0627\\u0634\\u0631\\u0628\\u0647 \\u0642\\u0628\\u0644 \\u0627\\u0644\\u0634\\u063A\\u0644\\u0629 \\u0627\\u0644\\u0635\\u0639\\u0628\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629."
t["I need sleep before I miss something important."] = "\\u0628\\u062F\\u064A \\u0646\\u0627\\u0645 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0641\\u0648\\u062A\\u0646\\u064A \\u0634\\u064A \\u0645\\u0647\\u0645."
t["I need sleep soon, but check the others too."] = "\\u0628\\u062F\\u064A \\u0646\\u0627\\u0645 \\u0642\\u0631\\u064A\\u0628\\u0627\\u064B\\u060C \\u0628\\u0633 \\u0634\\u0648\\u0641 \\u0627\\u0644\\u0628\\u0627\\u0642\\u064A\\u064A\\u0646 \\u0643\\u0645\\u0627\\u0646."
t["I need some privacy and a clear exit."] = "\\u0628\\u062F\\u064A \\u0634\\u0648\\u064A\\u0629 \\u062E\\u0635\\u0648\\u0635\\u064A\\u0629 \\u0648\\u0645\\u062E\\u0631\\u062C \\u0645\\u0641\\u062A\\u0648\\u062D."
t["I need something that can break ground, not just my hands."] = "\\u0628\\u062F\\u064A \\u0634\\u064A \\u064A\\u0643\\u0633\\u0631 \\u0627\\u0644\\u0623\\u0631\\u0636\\u060C \\u0645\\u0648 \\u0628\\u0633 \\u0625\\u064A\\u062F\\u064A\\u064A."
t["I need something to eat soon."] = "\\u0628\\u062F\\u064A \\u0622\\u0643\\u0644 \\u0634\\u064A \\u0642\\u0631\\u064A\\u0628\\u0627\\u064B."
t["I need something useful to do before I start climbing the walls."] = "\\u0628\\u062F\\u064A \\u0634\\u063A\\u0644\\u0629 \\u062A\\u0646\\u0641\\u0639 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0627\\u0637\\u0644\\u0639 \\u0639\\u0627\\u0644\\u062D\\u064A\\u0637\\u0627\\u0646."
t["I need space on my left!"] = "\\u0628\\u062F\\u064A \\u0645\\u0637\\u0631\\u062D \\u0639\\u064A\\u0633\\u0627\\u0631\\u064A!"
t["I need support here! Now!"] = "\\u0628\\u062F\\u064A \\u062F\\u0639\\u0645 \\u0647\\u0648\\u0646! \\u0647\\u0644\\u0623!"
t["I need the pressure to stop for a moment."] = "\\u0628\\u062F\\u064A \\u0627\\u0644\\u0636\\u063A\\u0637 \\u064A\\u0648\\u0642\\u0641 \\u0644\\u062D\\u0638\\u0629."
t["I need things slow and simple for a while."] = "\\u0628\\u062F\\u064A \\u0627\\u0644\\u0623\\u0645\\u0648\\u0631 \\u0639\\u0627\\u0644\\u0628\\u0637\\u064A\\u0621 \\u0648\\u0628\\u0633\\u064A\\u0637\\u0629 \\u0634\\u0648\\u064A."
t["I need this to be a good sign, so let it be one."] = "\\u0628\\u062F\\u064A \\u0647\\u0627\\u062F \\u064A\\u0643\\u0648\\u0646 \\u0641\\u0627\\u0644 \\u062E\\u064A\\u0631\\u060C \\u0641\\u062E\\u0644\\u064A\\u0647 \\u064A\\u0643\\u0648\\u0646."
t["I need to be alone for a while."] = "\\u0628\\u062F\\u064A \\u0643\\u0648\\u0646 \\u0644\\u062D\\u0627\\u0644\\u064A \\u0634\\u0648\\u064A."
t["I need to check the doors again. All of them."] = "\\u0644\\u0627\\u0632\\u0645 \\u0634\\u0648\\u0641 \\u0627\\u0644\\u0623\\u0628\\u0648\\u0627\\u0628 \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629. \\u0643\\u0644\\u0647\\u0627."
t["I need to finish what I'm doing first."] = "\\u0644\\u0627\\u0632\\u0645 \\u062E\\u0644\\u0651\\u0635 \\u0627\\u0644\\u0644\\u064A \\u0628\\u0625\\u064A\\u062F\\u064A \\u0623\\u0648\\u0644 \\u0634\\u064A."
t["I need to let some of this out."] = "\\u0644\\u0627\\u0632\\u0645 \\u0637\\u0644\\u0651\\u0639 \\u0634\\u0648\\u064A\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u0644\\u064A \\u062C\\u0648\\u0627\\u062A\\u064A."
t["I need to move before I wear a hole in the floor."] = "\\u0628\\u062F\\u064A \\u0627\\u062A\\u062D\\u0631\\u0643 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0627\\u0639\\u0645\\u0644 \\u062D\\u0641\\u0631\\u0629 \\u0628\\u0627\\u0644\\u0623\\u0631\\u0636 \\u0645\\u0646 \\u0627\\u0644\\u0645\\u0634\\u064A."
t["I need to rest soon."] = "\\u0644\\u0627\\u0632\\u0645 \\u0627\\u0631\\u062A\\u0627\\u062D \\u0642\\u0631\\u064A\\u0628\\u0627\\u064B."
t["I need to say what failed, then fix it."] = "\\u0644\\u0627\\u0632\\u0645 \\u0642\\u0648\\u0644 \\u0634\\u0648 \\u0641\\u0634\\u0644\\u060C \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0646\\u0635\\u0644\\u062D\\u0647."
t["I need to sit down for a while."] = "\\u0628\\u062F\\u064A \\u0627\\u0642\\u0639\\u062F \\u0634\\u0648\\u064A."
t["I need to sleep now."] = "\\u0644\\u0627\\u0632\\u0645 \\u0646\\u0627\\u0645 \\u0647\\u0644\\u0623."
t["I need to tell someone, and it's you. I was bitten."] = "\\u0644\\u0627\\u0632\\u0645 \\u062E\\u0628\\u0631 \\u062D\\u062F\\u0627\\u060C \\u0648\\u0647\\u0627\\u0644\\u062D\\u062F\\u0627 \\u0625\\u0646\\u062A. \\u0627\\u0646\\u0639\\u0636\\u0651\\u064A\\u062A."
t["I need to understand it myself before I tell anyone."] = "\\u0644\\u0627\\u0632\\u0645 \\u0627\\u0641\\u0647\\u0645\\u0647\\u0627 \\u0623\\u0646\\u0627 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062E\\u0628\\u0631 \\u062D\\u062F\\u0627."
t["I need treatment and a clean bandage."] = "\\u0628\\u062F\\u064A \\u0639\\u0644\\u0627\\u062C \\u0648\\u0634\\u0627\\u0634 \\u0646\\u0636\\u064A\\u0641."
t["I need two nails to secure this properly."] = "\\u0628\\u062F\\u064A \\u0628\\u0633\\u0645\\u0627\\u0631\\u064A\\u0646 \\u0644\\u062B\\u0628\\u0651\\u062A\\u0647\\u0627 \\u0645\\u062A\\u0644 \\u0627\\u0644\\u062E\\u0644\\u0642."
t["I need two nails."] = "\\u0628\\u062F\\u064A \\u0628\\u0633\\u0645\\u0627\\u0631\\u064A\\u0646."
t["I need water now."] = "\\u0628\\u062F\\u064A \\u0645\\u064A \\u0647\\u0644\\u0623."
t["I need water soon."] = "\\u0628\\u062F\\u064A \\u0645\\u064A \\u0642\\u0631\\u064A\\u0628\\u0627\\u064B."
t["I need water. Please don't give me someone else's last bottle."] = "\\u0628\\u062F\\u064A \\u0645\\u064A. \\u0628\\u0633 \\u0644\\u0627 \\u062A\\u0639\\u0637\\u064A\\u0646\\u064A \\u0622\\u062E\\u0631 \\u0642\\u0646\\u064A\\u0646\\u0629 \\u0644\\u062D\\u062F\\u0627."
t["I need you to forgive yourself, %1."] = "\\u0628\\u062F\\u064A \\u064A\\u0627\\u0643 \\u062A\\u0633\\u0627\\u0645\\u062D \\u062D\\u0627\\u0644\\u0643 \\u064A\\u0627 %1."
t["I need you to hear it once more: you are my family, and I love you."] = "\\u0628\\u062F\\u064A \\u062A\\u0633\\u0645\\u0639\\u0647\\u0627 \\u0645\\u0631\\u0629 \\u0643\\u0645\\u0627\\u0646: \\u0625\\u0646\\u062A \\u0639\\u064A\\u0644\\u062A\\u064A, \\u0648\\u0628\\u062D\\u0628\\u0643."
t["I need you to know before anyone else. It's a bite."] = "\\u0644\\u0627\\u0632\\u0645 \\u062A\\u0639\\u0631\\u0641 \\u0642\\u0628\\u0644 \\u0623\\u064A \\u062D\\u062F\\u0627. \\u0647\\u064A \\u0639\\u0636\\u0629."
t["I need you to know something is wrong. It feels like Knox symptoms."] = "\\u0644\\u0627\\u0632\\u0645 \\u062A\\u0639\\u0631\\u0641 \\u0625\\u0646\\u0647 \\u0641\\u064A \\u0634\\u064A \\u0645\\u0648 \\u0637\\u0628\\u064A\\u0639\\u064A. \\u062D\\u0627\\u0633\\u0629 \\u0623\\u0639\\u0631\\u0627\\u0636 \\u0646\\u0648\\u0643\\u0633."
t["I needed that thought more than I knew."] = "\\u0643\\u0646\\u062A \\u0645\\u062D\\u062A\\u0627\\u062C\\u0629 \\u0647\\u0627\\u0644\\u0641\\u0643\\u0631\\u0629 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0627 \\u0643\\u0646\\u062A \\u0639\\u0627\\u0631\\u0641\\u0629."
t["I never returned a library book. That fine is enormous as hell now."] = "\\u0645\\u0627 \\u0631\\u062C\\u0639\\u062A \\u0643\\u062A\\u0627\\u0628 \\u0644\\u0644\\u0645\\u0643\\u062A\\u0628\\u0629. \\u0627\\u0644\\u063A\\u0631\\u0627\\u0645\\u0629 \\u0635\\u0627\\u0631\\u062A \\u0642\\u062F \\u062C\\u0647\\u0646\\u0645 \\u0647\\u0644\\u0623."
t["I never returned a library book. That fine is enormous now."] = "\\u0645\\u0627 \\u0631\\u062C\\u0639\\u062A \\u0643\\u062A\\u0627\\u0628 \\u0644\\u0644\\u0645\\u0643\\u062A\\u0628\\u0629. \\u0627\\u0644\\u063A\\u0631\\u0627\\u0645\\u0629 \\u0635\\u0627\\u0631\\u062A \\u0636\\u062E\\u0645\\u0629 \\u0647\\u0644\\u0623."
t["I never thought I'd envy a highway rest stop."] = "\\u0645\\u0627 \\u062A\\u0648\\u0642\\u0639\\u062A \\u064A\\u0648\\u0645 \\u0627\\u062D\\u0633\\u062F \\u0627\\u0633\\u062A\\u0631\\u0627\\u062D\\u0629 \\u0639\\u0627\\u0644\\u0623\\u0648\\u062A\\u0648\\u0633\\u062A\\u0631\\u0627\\u062F."
t["I never thought a radio lesson would matter this much."] = "\\u0645\\u0627 \\u062A\\u0648\\u0642\\u0639\\u062A \\u062F\\u0631\\u0633 \\u0639\\u0627\\u0644\\u0631\\u0627\\u062F\\u064A\\u0648 \\u064A\\u0641\\u0631\\u0642 \\u0647\\u0627\\u0644\\u0642\\u062F."
t["I never thought television would teach me something we need."] = "\\u0639\\u0645\\u0631\\u064A \\u0645\\u0627 \\u062A\\u0648\\u0642\\u0639\\u062A \\u0627\\u0644\\u062A\\u0644\\u0641\\u0632\\u064A\\u0648\\u0646 \\u064A\\u0639\\u0644\\u0645\\u0646\\u064A \\u0634\\u064A \\u0646\\u062D\\u0646\\u0627 \\u0628\\u062D\\u0627\\u062C\\u062A\\u0647."
t["I offered peace. You answered with a blow."] = "\\u0639\\u0631\\u0636\\u062A \\u0639\\u0644\\u064A\\u0643 \\u0627\\u0644\\u0633\\u0644\\u0627\\u0645. \\u0631\\u062F\\u064A\\u062A \\u0628\\u0636\\u0631\\u0628\\u0629."
t["I owe you one."] = "\\u0625\\u0644\\u0643 \\u0639\\u0646\\u062F\\u064A \\u0648\\u062D\\u062F\\u0629."
t["I priced the next mile in batteries. It's cheap."] = "\\u0633\\u0639\\u0651\\u0631\\u062A \\u0627\\u0644\\u0645\\u064A\\u0644 \\u0627\\u0644\\u062C\\u0627\\u064A \\u0628\\u0627\\u0644\\u0628\\u0637\\u0627\\u0631\\u064A\\u0627\\u062A. \\u0631\\u062E\\u064A\\u0635."
t["I pulled too hard. Need a gentler hand."] = "\\u0634\\u062F\\u064A\\u062A \\u0643\\u062A\\u064A\\u0631. \\u0628\\u062F\\u0647\\u0627 \\u0625\\u064A\\u062F \\u0623\\u0646\\u0639\\u0645."
t["I reckon this could work. That's more than I'd have said before."] = "\\u0634\\u0643\\u0644\\u0647\\u0627 \\u0645\\u0645\\u0643\\u0646 \\u062A\\u0645\\u0634\\u064A. \\u0648\\u0647\\u0627\\u062F \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0645\\u0627 \\u0643\\u0646\\u062A \\u0631\\u062D \\u0642\\u0648\\u0644 \\u0642\\u0628\\u0644."
t["I remember %1. I don't want any of us to forget."] = "\\u0623\\u0646\\u0627 \\u0645\\u062A\\u0630\\u0643\\u0631\\u0629 %1. \\u0648\\u0645\\u0627 \\u0628\\u062F\\u064A \\u062D\\u062F\\u0627 \\u0645\\u0646\\u0627 \\u064A\\u0646\\u0633\\u0649."
t["I remember a lamp like that. Warm light on the tablecloth."] = "\\u0628\\u062A\\u0630\\u0643\\u0631 \\u0644\\u0645\\u0628\\u0629 \\u0645\\u062A\\u0644\\u0647\\u0627. \\u0636\\u0648 \\u062F\\u0627\\u0641\\u064A \\u0639\\u0627\\u0644\\u0634\\u0631\\u0634\\u0641."
t["I remember triage tags. We never had enough hands for every patient."] = "\\u0628\\u062A\\u0630\\u0643\\u0631 \\u0628\\u0637\\u0627\\u0642\\u0627\\u062A \\u0627\\u0644\\u0641\\u0631\\u0632. \\u0639\\u0645\\u0631\\u0646\\u0627 \\u0645\\u0627 \\u0643\\u0627\\u0646 \\u0639\\u0646\\u0627 \\u0625\\u064A\\u062F\\u064A\\u0646 \\u0644\\u0643\\u0644 \\u0645\\u0631\\u064A\\u0636."
t["I reorganised the shelves in my head. They're better now."] = "\\u0631\\u062A\\u0628\\u062A \\u0627\\u0644\\u0631\\u0641\\u0648\\u0641 \\u0628\\u0631\\u0627\\u0633\\u064A. \\u0635\\u0627\\u0631\\u0648\\u0627 \\u0623\\u062D\\u0633\\u0646."
t["I said I'd watch your back. I meant it to the end."] = "\\u0642\\u0644\\u062A \\u0631\\u062D \\u0627\\u062D\\u0645\\u064A \\u0636\\u0647\\u0631\\u0643. \\u0648\\u0639\\u0646\\u064A\\u062A\\u0647\\u0627 \\u0644\\u0644\\u0622\\u062E\\u0631."
t["I said ceasefire, not surrender!"] = "\\u0642\\u0644\\u062A \\u0647\\u062F\\u0646\\u0629\\u060C \\u0645\\u0648 \\u0627\\u0633\\u062A\\u0633\\u0644\\u0627\\u0645!"
t["I said stop! I'm backing away!"] = "\\u0642\\u0644\\u062A\\u0644\\u0643 \\u0648\\u0642\\u0641! \\u0639\\u0645 \\u0627\\u0631\\u062C\\u0639 \\u0644\\u0648\\u0631\\u0627!"
t["I said watch it! Keep your distance."] = "\\u0642\\u0644\\u062A\\u0644\\u0643 \\u0627\\u0646\\u062A\\u0628\\u0647! \\u0627\\u0628\\u0639\\u062F \\u0639\\u0646\\u064A."
t["I saved this for you. Would you take it?"] = "\\u062E\\u0628\\u064A\\u062A \\u0647\\u0627\\u0644\\u0634\\u064A \\u0625\\u0644\\u0643. \\u0628\\u062A\\u0627\\u062E\\u062F\\u0647?"
t["I saw nothing. That's our story."] = "\\u0645\\u0627 \\u0634\\u0641\\u062A \\u0634\\u064A. \\u0647\\u064A \\u0642\\u0635\\u062A\\u0646\\u0627."
t["I saw the scales, then nothing. Clever little thief."] = "\\u0634\\u0641\\u062A \\u0627\\u0644\\u0642\\u0634\\u0648\\u0631 \\u0648\\u0628\\u0639\\u062F\\u064A\\u0646 \\u0648\\u0644\\u0627 \\u0634\\u064A. \\u062D\\u0631\\u0627\\u0645\\u064A\\u0629 \\u0635\\u063A\\u064A\\u0631\\u0629 \\u0648\\u0634\\u0627\\u0637\\u0631\\u0629."
t["I see one. Please let it be alone."] = "\\u0634\\u0627\\u064A\\u0641\\u0629 \\u0648\\u0627\\u062D\\u062F. \\u064A\\u0627 \\u0631\\u0628 \\u064A\\u0643\\u0648\\u0646 \\u0644\\u062D\\u0627\\u0644\\u0647."
t["I set this aside for you. It might help."] = "\\u062D\\u0637\\u064A\\u062A\\u0647 \\u0639\\u0644\\u0649 \\u062C\\u0646\\u0628 \\u0625\\u0644\\u0643. \\u064A\\u0645\\u0643\\u0646 \\u064A\\u0641\\u064A\\u062F\\u0643."
t["I should have said more while %1 was still here."] = "\\u0643\\u0627\\u0646 \\u0644\\u0627\\u0632\\u0645 \\u0642\\u0648\\u0644 \\u0623\\u0643\\u062A\\u0631 \\u0644\\u0640%1 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u064A\\u0641\\u0648\\u062A \\u0627\\u0644\\u0623\\u0648\\u0627\\u0646."
t["I should remember what they just said."] = "\\u0644\\u0627\\u0632\\u0645 \\u0627\\u062A\\u0630\\u0643\\u0631 \\u0634\\u0648 \\u0642\\u0627\\u0644\\u0648\\u0627 \\u0647\\u0644\\u0623."
t["I slipped. That is not the same as surrendering."] = "\\u0632\\u0644\\u0642\\u062A. \\u0648\\u0647\\u0627\\u062F \\u0645\\u0648 \\u0627\\u0633\\u062A\\u0633\\u0644\\u0627\\u0645."
t["I spared you, and you came back swinging."] = "\\u062A\\u0631\\u0643\\u062A\\u0643 \\u0639\\u0627\\u064A\\u0634\\u060C \\u0648\\u0631\\u062C\\u0639\\u062A \\u062A\\u0636\\u0631\\u0628."
t["I spent half the day fixing things that broke yesterday."] = "\\u0646\\u0635 \\u0646\\u0647\\u0627\\u0631\\u064A \\u0631\\u0627\\u062D \\u0648\\u0623\\u0646\\u0627 \\u0635\\u0644\\u0651\\u062D \\u0634\\u063A\\u0644\\u0627\\u062A \\u0627\\u0646\\u0643\\u0633\\u0631\\u062A \\u0645\\u0628\\u0627\\u0631\\u062D."
t["I still catch myself remembering %1 at the strangest moments."] = "\\u0644\\u0633\\u0627 \\u0628\\u0644\\u0627\\u0642\\u064A \\u062D\\u0627\\u0644\\u064A \\u0639\\u0645 \\u0627\\u062A\\u0630\\u0643\\u0631 %1 \\u0628\\u0623\\u063A\\u0631\\u0628 \\u0627\\u0644\\u0623\\u0648\\u0642\\u0627\\u062A."
t["I still need to know I can say no to you."] = "\\u0644\\u0633\\u0627 \\u0644\\u0627\\u0632\\u0645 \\u0627\\u0639\\u0631\\u0641 \\u0625\\u0646\\u064A \\u0628\\u0642\\u062F\\u0631 \\u0642\\u0644\\u0643 \\u0644\\u0623."
t["I still watch the door. I don't watch you the same way."] = "\\u0644\\u0633\\u0627 \\u0628\\u0631\\u0627\\u0642\\u0628 \\u0627\\u0644\\u0628\\u0627\\u0628. \\u0628\\u0633 \\u0625\\u0646\\u062A \\u0645\\u0627 \\u0639\\u0645 \\u0631\\u0627\\u0642\\u0628\\u0643 \\u0645\\u062A\\u0644 \\u0642\\u0628\\u0644."
t["I stopped %1 after a problem. Next try is in %2."] = "\\u0648\\u0642\\u0641\\u062A %1 \\u0628\\u0639\\u062F \\u0645\\u0634\\u0643\\u0644\\u0629. \\u0627\\u0644\\u0645\\u062D\\u0627\\u0648\\u0644\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629 \\u0628\\u0639\\u062F %2."
t["I stopped once. I won't stop again."] = "\\u0648\\u0642\\u0641\\u062A \\u0645\\u0631\\u0629. \\u0645\\u0627 \\u0631\\u062D \\u0648\\u0642\\u0641 \\u062A\\u0627\\u0646\\u064A."
t["I stopped thinking of this as an arrangement a long time ago. You are family."] = "\\u0645\\u0646 \\u0632\\u0645\\u0627\\u0646 \\u0628\\u0637\\u0651\\u0644\\u062A \\u0634\\u0648\\u0641\\u0647\\u0627 \\u0635\\u0641\\u0642\\u0629. \\u0625\\u0646\\u062A \\u0635\\u0631\\u062A \\u0623\\u0647\\u0644\\u064A."
t["I swear, one more bad surprise and I'm going to lose it."] = "\\u0648\\u0627\\u0644\\u0644\\u0647 \\u0645\\u0641\\u0627\\u062C\\u0623\\u0629 \\u0639\\u0627\\u0637\\u0644\\u0629 \\u0643\\u0645\\u0627\\u0646 \\u0648\\u0628\\u0641\\u0642\\u062F \\u0639\\u0642\\u0644\\u064A."
t["I talked it through with myself. I am staying."] = "\\u062D\\u0643\\u064A\\u062A \\u0645\\u0639 \\u062D\\u0627\\u0644\\u064A \\u0648\\u062D\\u0633\\u0645\\u062A\\u0647\\u0627. \\u0623\\u0646\\u0627 \\u0628\\u0627\\u0642\\u064A\\u0629."
t["I think I can face the road again."] = "\\u0628\\u0638\\u0646 \\u0635\\u0627\\u0631 \\u0641\\u064A\\u0646\\u064A \\u0627\\u0631\\u062C\\u0639 \\u0644\\u0644\\u0637\\u0631\\u064A\\u0642."
t["I think about tomorrow now. You're usually in it."] = "\\u0635\\u0631\\u062A \\u0641\\u0643\\u0631 \\u0628\\u0628\\u0643\\u0631\\u0627. \\u0648\\u063A\\u0627\\u0644\\u0628\\u0627\\u064B \\u0628\\u062A\\u0643\\u0648\\u0646 \\u0641\\u064A\\u0647."
t["I think better when nobody is watching me think."] = "\\u0628\\u0641\\u0643\\u0631 \\u0623\\u062D\\u0633\\u0646 \\u0644\\u0645\\u0627 \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0643\\u0648\\u0646 \\u0639\\u0645 \\u064A\\u0637\\u0644\\u0651\\u0639 \\u0639\\u0644\\u064A\\u064A \\u0648\\u0623\\u0646\\u0627 \\u0628\\u0641\\u0643\\u0631."
t["I think the best books leave room to disagree, %1."] = "\\u0628\\u0638\\u0646 \\u0623\\u062D\\u0633\\u0646 \\u0627\\u0644\\u0643\\u062A\\u0628 \\u0628\\u062A\\u062A\\u0631\\u0643 \\u0645\\u062D\\u0644 \\u0644\\u0644\\u062E\\u0644\\u0627\\u0641 \\u064A\\u0627 %1."
t["I think the plan works if we stay disciplined."] = "\\u0628\\u0638\\u0646 \\u0627\\u0644\\u062E\\u0637\\u0629 \\u0628\\u062A\\u0632\\u0628\\u0637 \\u0625\\u0630\\u0627 \\u0636\\u0644\\u064A\\u0646\\u0627 \\u0645\\u0646\\u0636\\u0628\\u0637\\u064A\\u0646."
t["I think they can. It takes more than saying it, though."] = "\\u0628\\u0638\\u0646 \\u0628\\u064A\\u0642\\u062F\\u0631\\u0648\\u0627. \\u0628\\u0633 \\u0628\\u062F\\u0647\\u0627 \\u0623\\u0643\\u062A\\u0631 \\u0645\\u0646 \\u0627\\u0644\\u062D\\u0643\\u064A."
t["I think this partnership has a chance."] = "\\u062D\\u0627\\u0633\\u0629 \\u0647\\u0627\\u0644\\u0634\\u0631\\u0627\\u0643\\u0629 \\u0625\\u0644\\u0647\\u0627 \\u0623\\u0645\\u0644."
t["I think this place liked its old owners better."] = "\\u0628\\u0638\\u0646 \\u0647\\u0627\\u0644\\u0645\\u062D\\u0644 \\u0643\\u0627\\u0646 \\u064A\\u062D\\u0628 \\u0623\\u0635\\u062D\\u0627\\u0628\\u0647 \\u0627\\u0644\\u0642\\u062F\\u0627\\u0645 \\u0623\\u0643\\u062A\\u0631."
t["I thought I knew where this was going. I was wrong."] = "\\u0641\\u0643\\u0631\\u062A \\u0628\\u0639\\u0631\\u0641 \\u0648\\u064A\\u0646 \\u0631\\u0627\\u064A\\u062D\\u0629 \\u0627\\u0644\\u0642\\u0635\\u0629. \\u0637\\u0644\\u0639\\u062A \\u063A\\u0644\\u0637\\u0627\\u0646\\u0629."
t["I thought I was ready. I'm not."] = "\\u0643\\u0646\\u062A \\u0645\\u0641\\u0643\\u0631\\u0629 \\u062D\\u0627\\u0644\\u064A \\u062C\\u0627\\u0647\\u0632\\u0629. \\u0637\\u0644\\u0639\\u062A \\u0644\\u0623."
t["I thought we'd get one more morning."] = "\\u0643\\u0646\\u062A \\u0645\\u0641\\u0643\\u0631\\u0629 \\u0641\\u064A \\u0635\\u0628\\u062D\\u064A\\u0629 \\u0643\\u0645\\u0627\\u0646."
t["I took a chance following you. Make it mean something - get me up!"] = "\\u062E\\u0627\\u0637\\u0631\\u062A \\u0644\\u0645\\u0627 \\u0644\\u062D\\u0642\\u062A\\u0643. \\u062E\\u0644\\u064A\\u0647\\u0627 \\u062A\\u0633\\u0648\\u0649 - \\u0642\\u0648\\u0645\\u0646\\u064A!"
t["I tried asking the log to split itself. It declined."] = "\\u0637\\u0644\\u0628\\u062A \\u0645\\u0646 \\u0627\\u0644\\u062C\\u0630\\u0639 \\u064A\\u0634\\u0642 \\u062D\\u0627\\u0644\\u0647. \\u0627\\u0639\\u062A\\u0630\\u0631."
t["I tried pulling. The barricade was unimpressed."] = "\\u0634\\u062F\\u0651\\u064A\\u062A. \\u0627\\u0644\\u062D\\u0627\\u062C\\u0632 \\u0645\\u0627 \\u0627\\u0647\\u062A\\u0632 \\u0648\\u0644\\u0627 \\u0627\\u0647\\u062A\\u0645."
t["I tried to leave it there. Now I can't."] = "\\u062D\\u0627\\u0648\\u0644\\u062A \\u062E\\u0644\\u064A\\u0647\\u0627 \\u0647\\u0648\\u0646. \\u0647\\u0644\\u0623 \\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A."
t["I trust questions that leave space for new evidence."] = "\\u0628\\u0648\\u062B\\u0642 \\u0628\\u0627\\u0644\\u0623\\u0633\\u0626\\u0644\\u0629 \\u0627\\u0644\\u0644\\u064A \\u0628\\u062A\\u062A\\u0631\\u0643 \\u0645\\u062D\\u0644 \\u0644\\u062F\\u0644\\u064A\\u0644 \\u062C\\u062F\\u064A\\u062F."
t["I trust you like family. That is the truth of it."] = "\\u0628\\u0648\\u062B\\u0642 \\u0641\\u064A\\u0643 \\u0645\\u062A\\u0644 \\u0623\\u0647\\u0644\\u064A. \\u0648\\u0647\\u064A \\u0627\\u0644\\u062D\\u0642\\u064A\\u0642\\u0629."
t["I trust you to know when I am gone, %1."] = "\\u0648\\u0627\\u062B\\u0642\\u0629 \\u0625\\u0646\\u0643 \\u0628\\u062A\\u0639\\u0631\\u0641 \\u0644\\u0645\\u0627 \\u0623\\u0643\\u0648\\u0646 \\u0631\\u062D\\u062A \\u064A\\u0627 %1."
t["I trust you with my life. That is not something I say lightly."] = "\\u0628\\u0623\\u0645\\u0651\\u0646\\u0643 \\u0639\\u0644\\u0649 \\u0631\\u0648\\u062D\\u064A. \\u0648\\u0647\\u064A \\u0645\\u0648 \\u0643\\u0644\\u0645\\u0629 \\u0628\\u0642\\u0648\\u0644\\u0647\\u0627 \\u0628\\u0633\\u0647\\u0648\\u0644\\u0629."
t["I trust you, so you hear it first. I was bitten."] = "\\u0628\\u0648\\u062B\\u0642 \\u0641\\u064A\\u0643\\u060C \\u0641\\u0625\\u0646\\u062A \\u0623\\u0648\\u0644 \\u0648\\u0627\\u062D\\u062F \\u0628\\u064A\\u0633\\u0645\\u0639. \\u0627\\u0646\\u0639\\u0636\\u0651\\u064A\\u062A."
t["I trust you. From now on, I am one of yours."] = "\\u0628\\u0648\\u062B\\u0642 \\u0641\\u064A\\u0643. \\u0645\\u0646 \\u0647\\u0644\\u0623 \\u0648\\u0631\\u0627\\u064A\\u062D \\u0623\\u0646\\u0627 \\u0645\\u0646\\u0643\\u0646."
t["I trust you. I'm still checking the way out."] = "\\u0628\\u0648\\u062B\\u0642 \\u0641\\u064A\\u0643. \\u0648\\u0628\\u0631\\u0636\\u0648 \\u0639\\u0645 \\u0634\\u064A\\u0651\\u0643 \\u0639\\u0627\\u0644\\u0645\\u062E\\u0631\\u062C."
t["I trust you. That's why you're hearing this. I got bit."] = "\\u0628\\u0648\\u062B\\u0642 \\u0641\\u064A\\u0643. \\u0645\\u0634\\u0627\\u0646 \\u0647\\u064A\\u0643 \\u0639\\u0645 \\u062A\\u0633\\u0645\\u0639\\u0647\\u0627. \\u0627\\u0646\\u0639\\u0636\\u0651\\u064A\\u062A."
t["I trusted you with every bad road. Trust me when I tell you to go."] = "\\u0623\\u0645\\u0646\\u062A\\u0643 \\u0628\\u0643\\u0644 \\u0637\\u0631\\u064A\\u0642 \\u0632\\u0641\\u062A. \\u0623\\u0645\\u0646\\u064A \\u0644\\u0645\\u0627 \\u0642\\u0644\\u0643 \\u0631\\u0648\\u062D."
t["I trusted you with my back. Don't make me regret it."] = "\\u0623\\u0645\\u0646\\u062A\\u0643 \\u0639\\u0644\\u0649 \\u0636\\u0647\\u0631\\u064A. \\u0644\\u0627 \\u062A\\u062E\\u0644\\u064A\\u0646\\u064A \\u0627\\u0646\\u062F\\u0645."
t["I trusted you with my life, %1! I'm trusting you now!"] = "\\u0623\\u0645\\u0646\\u062A\\u0643 \\u0639\\u0644\\u0649 \\u062D\\u064A\\u0627\\u062A\\u064A \\u064A\\u0627 %1! \\u0648\\u0639\\u0645 \\u0623\\u0645\\u0646\\u0643 \\u0647\\u0644\\u0623!"
t["I turned the page because I couldn't let that stand."] = "\\u0642\\u0644\\u0628\\u062A \\u0627\\u0644\\u0635\\u0641\\u062D\\u0629 \\u0644\\u0623\\u0646\\u0648 \\u0645\\u0627 \\u0641\\u064A\\u0646\\u064A \\u0627\\u0633\\u0643\\u062A \\u0639\\u0646 \\u0647\\u0627\\u0644\\u062D\\u0643\\u064A."
t["I understand what you're offering. Leave it with me."] = "\\u0641\\u0647\\u0645\\u0627\\u0646\\u0629 \\u0634\\u0648 \\u0639\\u0645 \\u062A\\u0639\\u0631\\u0636. \\u062E\\u0644\\u064A\\u0647\\u0627 \\u0639\\u0646\\u062F\\u064A."
t["I understand. Take care of yourself."] = "\\u0641\\u0647\\u0645\\u062A. \\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0643 \\u0639\\u0644\\u0649 \\u062D\\u0627\\u0644\\u0643."
t["I understand. We make do with what we have."] = "\\u0641\\u0647\\u0645\\u062A. \\u0645\\u0646\\u0645\\u0634\\u064A\\u0647\\u0627 \\u0628\\u0627\\u0644\\u0644\\u064A \\u0639\\u0646\\u0627."
t["I used to bring people to cells like these. I never liked the sound of the locks."] = "\\u0643\\u0646\\u062A \\u062C\\u064A\\u0628 \\u0646\\u0627\\u0633 \\u0644\\u0632\\u0646\\u0627\\u0632\\u064A\\u0646 \\u0645\\u062A\\u0644 \\u0647\\u064A. \\u0639\\u0645\\u0631\\u064A \\u0645\\u0627 \\u062D\\u0628\\u064A\\u062A \\u0635\\u0648\\u062A \\u0627\\u0644\\u0623\\u0642\\u0641\\u0627\\u0644."
t["I used to come here for boots. I'd still take a good pair."] = "\\u0643\\u0646\\u062A \\u0627\\u062C\\u064A \\u0645\\u0646 \\u0647\\u0648\\u0646 \\u0627\\u0634\\u062A\\u0631\\u064A \\u062C\\u0632\\u0645. \\u0644\\u0633\\u0627 \\u0628\\u0627\\u062E\\u062F \\u0648\\u062D\\u062F\\u0629 \\u0645\\u0646\\u064A\\u062D\\u0629."
t["I used to complain about crowded dinners. Can you believe that?"] = "\\u0643\\u0646\\u062A \\u0627\\u062A\\u0630\\u0645\\u0631 \\u0645\\u0646 \\u0627\\u0644\\u0639\\u0632\\u0627\\u064A\\u0645 \\u0627\\u0644\\u0645\\u0632\\u062F\\u062D\\u0645\\u0629. \\u0628\\u062A\\u0635\\u062F\\u0642\\u061F"
t["I used to complain about low water pressure."] = "\\u0643\\u0646\\u062A \\u0627\\u062A\\u0630\\u0645\\u0631 \\u0645\\u0646 \\u0636\\u0639\\u0641 \\u0627\\u0644\\u0645\\u064A."
t["I used to like a storm when I had a warm room to watch it from."] = "\\u0643\\u0646\\u062A \\u062D\\u0628 \\u0627\\u0644\\u0639\\u0627\\u0635\\u0641\\u0629 \\u0644\\u0645\\u0627 \\u0643\\u0627\\u0646 \\u0639\\u0646\\u062F\\u064A \\u0623\\u0648\\u0636\\u0629 \\u062F\\u0627\\u0641\\u064A\\u0629 \\u0627\\u062A\\u0641\\u0631\\u062C \\u0645\\u0646\\u0647\\u0627."
t["I used to think survival was winning. Now I'm less certain."] = "\\u0643\\u0646\\u062A \\u0641\\u0643\\u0631 \\u0627\\u0644\\u0646\\u062C\\u0627\\u0629 \\u064A\\u0639\\u0646\\u064A \\u0631\\u0628\\u062D. \\u0647\\u0644\\u0623 \\u0645\\u0648 \\u0645\\u062A\\u0623\\u0643\\u062F\\u0629."
t["I used to watch this with dinner."] = "\\u0643\\u0646\\u062A \\u0627\\u062A\\u0641\\u0631\\u062C \\u0639\\u0644\\u064A\\u0647 \\u0648\\u0623\\u0646\\u0627 \\u0639\\u0645 \\u0627\\u062A\\u0639\\u0634\\u0649."
t["I used to wheel patients down corridors like this. I can still hear the wheels."] = "\\u0643\\u0646\\u062A \\u0627\\u062F\\u0641\\u0634 \\u0645\\u0631\\u0636\\u0649 \\u0628\\u0645\\u0645\\u0631\\u0627\\u062A \\u0645\\u062A\\u0644 \\u0647\\u064A. \\u0644\\u0633\\u0627 \\u0628\\u0633\\u0645\\u0639 \\u0627\\u0644\\u062F\\u0648\\u0627\\u0644\\u064A\\u0628."
t["I used to yell 'one more rep' in gyms like this. Now I yell 'run'."] = "\\u0643\\u0646\\u062A \\u0635\\u0631\\u0651\\u062E \\u0643\\u0645\\u0627\\u0646 \\u0639\\u062F\\u0629 \\u0628\\u0646\\u0648\\u0627\\u062F\\u064A \\u0645\\u062A\\u0644 \\u0647\\u064A. \\u0647\\u0644\\u0623 \\u0628\\u0635\\u0631\\u0651\\u062E \\u0627\\u0631\\u0643\\u0636\\u0648\\u0627."
t["I want a book I can come back to after a hard day."] = "\\u0628\\u062F\\u064A \\u0643\\u062A\\u0627\\u0628 \\u0627\\u0631\\u062C\\u0639\\u0644\\u0647 \\u0628\\u0639\\u062F \\u064A\\u0648\\u0645 \\u0635\\u0639\\u0628."
t["I want a little company at supper. Ordinary company, for once."] = "\\u0628\\u062F\\u064A \\u0634\\u0648\\u064A\\u0629 \\u0648\\u0646\\u0633 \\u0639\\u0627\\u0644\\u0639\\u0634\\u0627. \\u0648\\u0646\\u0633 \\u0639\\u0627\\u062F\\u064A\\u060C \\u0644\\u0645\\u0631\\u0629 \\u0648\\u062D\\u062F\\u0629."
t["I want a proper reserve of clean bandages."] = "\\u0628\\u062F\\u064A \\u0627\\u062D\\u062A\\u064A\\u0627\\u0637\\u064A \\u0645\\u062D\\u062A\\u0631\\u0645 \\u0645\\u0646 \\u0627\\u0644\\u0634\\u0627\\u0634 \\u0627\\u0644\\u0646\\u0636\\u064A\\u0641."
t["I want clean bandages ready where anyone can find them."] = "\\u0628\\u062F\\u064A \\u0634\\u0627\\u0634 \\u0646\\u0636\\u064A\\u0641 \\u062C\\u0627\\u0647\\u0632 \\u0628\\u0645\\u0637\\u0631\\u062D \\u0627\\u0644\\u0643\\u0644 \\u0628\\u064A\\u0644\\u0627\\u0642\\u064A\\u0647."
t["I want our gear ready before we depend on it again."] = "\\u0628\\u062F\\u064A \\u0639\\u062F\\u062A\\u0646\\u0627 \\u062C\\u0627\\u0647\\u0632\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0646\\u0631\\u062C\\u0639 \\u0646\\u0639\\u062A\\u0645\\u062F \\u0639\\u0644\\u064A\\u0647\\u0627."
t["I want something to think through before we move again. %1 will do."] = "\\u0628\\u062F\\u064A \\u0634\\u064A \\u0641\\u0643\\u0631 \\u0641\\u064A\\u0647 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0646\\u062A\\u062D\\u0631\\u0643. %1 \\u0628\\u064A\\u0645\\u0634\\u064A \\u0627\\u0644\\u062D\\u0627\\u0644."
t["I want to check the worn straps and loose handles before we head out."] = "\\u0628\\u062F\\u064A \\u0627\\u0641\\u062D\\u0635 \\u0627\\u0644\\u062D\\u0632\\u0627\\u0645\\u0627\\u062A \\u0627\\u0644\\u062F\\u0627\\u064A\\u0628\\u0629 \\u0648\\u0627\\u0644\\u0645\\u0642\\u0627\\u0628\\u0636 \\u0627\\u0644\\u0631\\u062E\\u0648\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0646\\u0637\\u0644\\u0639."
t["I want to file a report. About every goddamn thing."] = "\\u0628\\u062F\\u064A \\u0642\\u062F\\u0651\\u0645 \\u0628\\u0644\\u0627\\u063A. \\u0639\\u0646 \\u0643\\u0644 \\u0647\\u0627\\u0644\\u0632\\u0641\\u062A."
t["I want to file a report. About everything."] = "\\u0628\\u062F\\u064A \\u0642\\u062F\\u0651\\u0645 \\u0628\\u0644\\u0627\\u063A. \\u0639\\u0646 \\u0643\\u0644 \\u0634\\u064A."
t["I want to hang my arm out the window. Bad goddamn idea out here."] = "\\u0628\\u062F\\u064A \\u0637\\u0627\\u0644\\u0639 \\u0625\\u064A\\u062F\\u064A \\u0645\\u0646 \\u0627\\u0644\\u0634\\u0628\\u0627\\u0643. \\u0641\\u0643\\u0631\\u0629 \\u0632\\u0641\\u062A \\u0647\\u0648\\u0646."
t["I want to hang my arm out the window. Bad idea out here."] = "\\u0628\\u062F\\u064A \\u0637\\u0627\\u0644\\u0639 \\u0625\\u064A\\u062F\\u064A \\u0645\\u0646 \\u0627\\u0644\\u0634\\u0628\\u0627\\u0643. \\u0641\\u0643\\u0631\\u0629 \\u0639\\u0627\\u0637\\u0644\\u0629 \\u0647\\u0648\\u0646."
t["I want to hear a voice that hasn't seen this place."] = "\\u0628\\u062F\\u064A \\u0627\\u0633\\u0645\\u0639 \\u0635\\u0648\\u062A \\u0645\\u0627 \\u0634\\u0627\\u0641 \\u0647\\u0627\\u0644\\u0645\\u062D\\u0644."
t["I want to help. I just don't have anything left to give."] = "\\u0628\\u062F\\u064A \\u0633\\u0627\\u0639\\u062F. \\u0628\\u0633 \\u0645\\u0627 \\u0636\\u0644 \\u0639\\u0646\\u062F\\u064A \\u0634\\u064A \\u0639\\u0637\\u064A\\u0647."
t["I want to knock on a door and ask for a cup of sugar."] = "\\u0628\\u062F\\u064A \\u062F\\u0642 \\u0628\\u0627\\u0628 \\u0648\\u0627\\u0637\\u0644\\u0628 \\u0641\\u0646\\u062C\\u0627\\u0646 \\u0633\\u0643\\u0631."
t["I want to make this place a little harder for the dead to enter."] = "\\u0628\\u062F\\u064A \\u0635\\u0639\\u0651\\u0628 \\u0639\\u0627\\u0644\\u0645\\u0648\\u062A\\u0649 \\u064A\\u062F\\u062E\\u0644\\u0648\\u0627 \\u0644\\u0647\\u0648\\u0646 \\u0634\\u0648\\u064A."
t["I want to recover something that still feels like mine."] = "\\u0628\\u062F\\u064A \\u0631\\u062C\\u0651\\u0639 \\u0634\\u064A \\u0644\\u0633\\u0627 \\u0628\\u062D\\u0633 \\u0625\\u0646\\u0647 \\u0625\\u0644\\u064A."
t["I want to repair our worn gear before it fails us."] = "\\u0628\\u062F\\u064A \\u0635\\u0644\\u0651\\u062D \\u0639\\u062F\\u062A\\u0646\\u0627 \\u0627\\u0644\\u0645\\u0647\\u062A\\u0631\\u064A\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062A\\u062E\\u0630\\u0644\\u0646\\u0627."
t["I want to see that demonstration twice before I try it."] = "\\u0628\\u062F\\u064A \\u0634\\u0648\\u0641 \\u0647\\u0627\\u0644\\u0634\\u0631\\u062D \\u0645\\u0631\\u062A\\u064A\\u0646 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062C\\u0631\\u0628."
t["I want to see the sky once more."] = "\\u0628\\u062F\\u064A \\u0634\\u0648\\u0641 \\u0627\\u0644\\u0633\\u0645\\u0627 \\u0645\\u0631\\u0629 \\u0643\\u0645\\u0627\\u0646."
t["I want to sort all the cans by colour. I'm resisting."] = "\\u0628\\u062F\\u064A \\u0631\\u062A\\u0628 \\u0643\\u0644 \\u0627\\u0644\\u0639\\u0644\\u0628 \\u062D\\u0633\\u0628 \\u0627\\u0644\\u0644\\u0648\\u0646. \\u0639\\u0645 \\u0642\\u0627\\u0648\\u0645."
t["I want to stack every chair in here into something tall."] = "\\u0628\\u062F\\u064A \\u0643\\u0648\\u0651\\u0645 \\u0643\\u0644 \\u0627\\u0644\\u0643\\u0631\\u0627\\u0633\\u064A \\u0647\\u0648\\u0646 \\u0648\\u0623\\u0639\\u0645\\u0644 \\u0634\\u064A \\u0639\\u0627\\u0644\\u064A."
t["I want to stand in it like a kid. Like a damn idiot."] = "\\u0628\\u062F\\u064A \\u0648\\u0642\\u0641 \\u062A\\u062D\\u062A\\u0647 \\u0645\\u062A\\u0644 \\u0627\\u0644\\u0648\\u0644\\u0627\\u062F. \\u0645\\u062A\\u0644 \\u0627\\u0644\\u0647\\u0628\\u0644\\u0629 \\u0627\\u0644\\u0645\\u0644\\u0639\\u0648\\u0646\\u0629."
t["I want to stand in it like a kid. Like an idiot."] = "\\u0628\\u062F\\u064A \\u0648\\u0642\\u0641 \\u062A\\u062D\\u062A\\u0647 \\u0645\\u062A\\u0644 \\u0627\\u0644\\u0648\\u0644\\u0627\\u062F. \\u0645\\u062A\\u0644 \\u0627\\u0644\\u0647\\u0628\\u0644\\u0629."
t["I want to start a rumour. There's nobody left to tell."] = "\\u0628\\u062F\\u064A \\u0637\\u0644\\u0651\\u0639 \\u0625\\u0634\\u0627\\u0639\\u0629. \\u0645\\u0627 \\u0636\\u0644 \\u062D\\u062F\\u0627 \\u0623\\u062E\\u0628\\u0631\\u0647."
t["I want to strengthen the openings we keep worrying about."] = "\\u0628\\u062F\\u064A \\u0642\\u0648\\u0651\\u064A \\u0627\\u0644\\u0641\\u062A\\u062D\\u0627\\u062A \\u0627\\u0644\\u0644\\u064A \\u0636\\u0644\\u064A\\u0646\\u0627 \\u0642\\u0644\\u0642\\u0627\\u0646\\u064A\\u0646 \\u0645\\u0646\\u0647\\u0627."
t["I want to test this idea before I trust it."] = "\\u0628\\u062F\\u064A \\u062C\\u0631\\u0628 \\u0647\\u0627\\u0644\\u0641\\u0643\\u0631\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0648\\u062B\\u0642 \\u0641\\u064A\\u0647\\u0627."
t["I want to trust you. Wanting isn't the hard part."] = "\\u0628\\u062F\\u064A \\u0627\\u0648\\u062B\\u0642 \\u0641\\u064A\\u0643. \\u0627\\u0644\\u0635\\u0639\\u0648\\u0628\\u0629 \\u0645\\u0648 \\u0628\\u0625\\u0646\\u064A \\u0628\\u062F\\u064A."
t["I want to try that when daylight comes."] = "\\u0628\\u062F\\u064A \\u062C\\u0631\\u0628\\u0647\\u0627 \\u0644\\u0645\\u0627 \\u064A\\u0637\\u0644\\u0639 \\u0627\\u0644\\u0636\\u0648."
t["I wanted more time as myself."] = "\\u0643\\u0627\\u0646 \\u0628\\u062F\\u064A \\u0648\\u0642\\u062A \\u0623\\u0643\\u062A\\u0631 \\u0648\\u0623\\u0646\\u0627 \\u0623\\u0646\\u0627."
t["I wanted to throw %1 across the room. Then I read it again."] = "\\u0643\\u0627\\u0646 \\u0628\\u062F\\u064A \\u0627\\u0636\\u0631\\u0628 %1 \\u0628\\u0627\\u0644\\u062D\\u064A\\u0637. \\u0628\\u0639\\u062F\\u064A\\u0646 \\u0631\\u062C\\u0639\\u062A \\u0642\\u0631\\u064A\\u062A\\u0647."
t["I warned you. Don't come close right now."] = "\\u062D\\u0630\\u0631\\u062A\\u0643. \\u0644\\u0627 \\u062A\\u0642\\u0631\\u0628 \\u0647\\u0644\\u0623."
t["I warned you. Now I'm fighting back."] = "\\u062D\\u0630\\u0631\\u062A\\u0643. \\u0647\\u0644\\u0623 \\u0639\\u0645 \\u0631\\u062F."
t["I was bitten out there. I am sorry."] = "\\u0627\\u0646\\u0639\\u0636\\u0651\\u064A\\u062A \\u0628\\u0631\\u0627. \\u0623\\u0646\\u0627 \\u0622\\u0633\\u0641\\u0629."
t["I was careful. I was always careful. Why wasn't that enough?"] = "\\u0643\\u0646\\u062A \\u062D\\u0631\\u064A\\u0635\\u0629. \\u0637\\u0648\\u0644 \\u0639\\u0645\\u0631\\u064A \\u062D\\u0631\\u064A\\u0635\\u0629. \\u0644\\u064A\\u0634 \\u0645\\u0627 \\u0643\\u0641\\u0651\\u0649\\u061F"
t["I was having a nice quiet minute, too."] = "\\u0648\\u0623\\u0646\\u0627 \\u0627\\u0644\\u0644\\u064A \\u0643\\u0646\\u062A \\u0645\\u0628\\u0633\\u0648\\u0637\\u0629 \\u0628\\u062F\\u0642\\u064A\\u0642\\u0629 \\u0647\\u062F\\u0648\\u0621."
t["I was hoping you would ask. Let's move."] = "\\u0643\\u0646\\u062A \\u0646\\u0627\\u0637\\u0631\\u0629 \\u062A\\u0633\\u0623\\u0644\\u0646\\u064A. \\u064A\\u0644\\u0627."
t["I was just doing my part, but I appreciate you saying it."] = "\\u0643\\u0646\\u062A \\u0639\\u0645 \\u0627\\u0639\\u0645\\u0644 \\u0627\\u0644\\u0644\\u064A \\u0639\\u0644\\u064A\\u064A\\u060C \\u0628\\u0633 \\u062D\\u0644\\u0648\\u0629 \\u0645\\u0646\\u0643 \\u0647\\u0627\\u0644\\u0643\\u0644\\u0645\\u0629."
t["I was lucky to have you beside me. Don't die beside me now."] = "\\u0643\\u0627\\u0646 \\u062D\\u0638\\u064A \\u062D\\u0644\\u0648 \\u0625\\u0646\\u0643 \\u062C\\u0646\\u0628\\u064A. \\u0644\\u0627 \\u062A\\u0645\\u0648\\u062A \\u062C\\u0646\\u0628\\u064A \\u0647\\u0644\\u0623."
t["I was scared before I met you. I'm less scared now."] = "\\u0643\\u0646\\u062A \\u062E\\u0627\\u064A\\u0641\\u0629 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u0623\\u0639\\u0631\\u0641\\u0643. \\u0647\\u0644\\u0623 \\u0623\\u0642\\u0644."
t["I was someone again when I was with you."] = "\\u0631\\u062C\\u0639\\u062A \\u062D\\u062F\\u0627 \\u0644\\u0645\\u0627 \\u0643\\u0646\\u062A \\u0645\\u0639\\u0643."
t["I was there too. You don't get to put all of that on me."] = "\\u0623\\u0646\\u0627 \\u0643\\u0646\\u062A \\u0647\\u0646\\u064A\\u0643 \\u0643\\u0645\\u0627\\u0646. \\u0645\\u0627 \\u0628\\u062A\\u0642\\u062F\\u0631 \\u062A\\u062D\\u0637 \\u0643\\u0644 \\u0634\\u064A \\u0639\\u0644\\u064A\\u064A."
t["I was thinking about the people we left behind. Let's keep moving soon."] = "\\u0643\\u0646\\u062A \\u0639\\u0645 \\u0641\\u0643\\u0631 \\u0628\\u0627\\u0644\\u0646\\u0627\\u0633 \\u0627\\u0644\\u0644\\u064A \\u062A\\u0631\\u0643\\u0646\\u0627\\u0647\\u0646. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u0645\\u0634\\u064A \\u0642\\u0631\\u064A\\u0628."
t["I was too quick. Next time I wait."] = "\\u0627\\u0633\\u062A\\u0639\\u062C\\u0644\\u062A. \\u0627\\u0644\\u0645\\u0631\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629 \\u0628\\u0633\\u062A\\u0646\\u0649."
t["I wasn't sure anyone noticed."] = "\\u0645\\u0627 \\u0643\\u0646\\u062A \\u0645\\u062A\\u0623\\u0643\\u062F\\u0629 \\u0625\\u0646\\u0648 \\u062D\\u062F\\u0627 \\u0627\\u0646\\u062A\\u0628\\u0647."
t["I will come for a trial run, nothing more yet."] = "\\u0631\\u062D \\u0627\\u062C\\u064A \\u0645\\u0634\\u0648\\u0627\\u0631 \\u062A\\u062C\\u0631\\u0628\\u0629\\u060C \\u0644\\u0633\\u0627 \\u0645\\u0648 \\u0623\\u0643\\u062A\\u0631."
t["I will feel better after one more check of the windows."] = "\\u0628\\u0631\\u062A\\u0627\\u062D \\u0623\\u0643\\u062A\\u0631 \\u0628\\u0639\\u062F \\u0645\\u0627 \\u0634\\u064A\\u0643 \\u0627\\u0644\\u0634\\u0628\\u0627\\u0628\\u064A\\u0643 \\u0643\\u0645\\u0627\\u0646 \\u0645\\u0631\\u0629."
t["I will guard it, but I want the doors and windows checked."] = "\\u0631\\u062D \\u0627\\u062D\\u0631\\u0633\\u0647\\u060C \\u0628\\u0633 \\u0628\\u062F\\u064A \\u0627\\u0644\\u0623\\u0628\\u0648\\u0627\\u0628 \\u0648\\u0627\\u0644\\u0634\\u0628\\u0627\\u0628\\u064A\\u0643 \\u0645\\u0641\\u062D\\u0648\\u0635\\u0629."
t["I will keep an eye out for useful supplies without slowing us down."] = "\\u0631\\u062D \\u0636\\u0644 \\u0645\\u0641\\u062A\\u062D\\u0629 \\u0639\\u0644\\u0649 \\u0634\\u064A \\u064A\\u0646\\u0641\\u0639 \\u0628\\u0644\\u0627 \\u0645\\u0627 \\u0646\\u062A\\u0623\\u062E\\u0631."
t["I will remember that. Thank you."] = "\\u0645\\u0627 \\u0631\\u062D \\u0627\\u0646\\u0633\\u0627\\u0647\\u0627. \\u0634\\u0643\\u0631\\u0627\\u064B."
t["I will take essentials and leave the junk behind."] = "\\u0628\\u0627\\u062E\\u062F \\u0627\\u0644\\u0636\\u0631\\u0648\\u0631\\u064A \\u0648\\u0628\\u062A\\u0631\\u0643 \\u0627\\u0644\\u062E\\u0631\\u062F\\u0629."
t["I wish I could tell the writer that these pages mattered."] = "\\u064A\\u0627 \\u0631\\u064A\\u062A \\u0641\\u064A\\u0646\\u064A \\u0642\\u0648\\u0644 \\u0644\\u0644\\u0643\\u0627\\u062A\\u0628 \\u0625\\u0646\\u0648 \\u0647\\u0627\\u0644\\u0635\\u0641\\u062D\\u0627\\u062A \\u0641\\u0631\\u0642\\u062A."
t["I wish I'd trusted you sooner. Go."] = "\\u064A\\u0627 \\u0631\\u064A\\u062A\\u0646\\u064A \\u0648\\u062B\\u0642\\u062A \\u0641\\u064A\\u0643 \\u0623\\u0628\\u0643\\u0631. \\u0631\\u0648\\u062D."
t["I wish it had gone differently. Be safe."] = "\\u064A\\u0627 \\u0631\\u064A\\u062A\\u0647\\u0627 \\u0645\\u0634\\u064A\\u062A \\u063A\\u064A\\u0631 \\u0647\\u064A\\u0643. \\u062F\\u064A\\u0631 \\u0628\\u0627\\u0644\\u0643."
t["I wish somebody had shown me this last month."] = "\\u064A\\u0627 \\u0631\\u064A\\u062A \\u062D\\u062F\\u0627 \\u0641\\u0631\\u062C\\u0627\\u0646\\u064A \\u064A\\u0627\\u0647\\u0627 \\u0645\\u0646 \\u0634\\u0647\\u0631."
t["I wish the others could see this bit."] = "\\u064A\\u0627 \\u0631\\u064A\\u062A \\u0627\\u0644\\u0628\\u0627\\u0642\\u064A\\u064A\\u0646 \\u064A\\u0634\\u0648\\u0641\\u0648\\u0627 \\u0647\\u0627\\u0644\\u0645\\u0642\\u0637\\u0639."
t["I wish the others had heard that bit."] = "\\u064A\\u0627 \\u0631\\u064A\\u062A \\u0627\\u0644\\u0628\\u0627\\u0642\\u064A\\u064A\\u0646 \\u0633\\u0645\\u0639\\u0648\\u0627 \\u0647\\u0627\\u0644\\u0645\\u0642\\u0637\\u0639."
t["I wish we had met before the world ended."] = "\\u064A\\u0627 \\u0631\\u064A\\u062A \\u062A\\u0639\\u0631\\u0641\\u0646\\u0627 \\u0642\\u0628\\u0644 \\u0645\\u0627 \\u062A\\u062E\\u0644\\u0635 \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627."
t["I wish you had met the version of me that had more time."] = "\\u064A\\u0627 \\u0631\\u064A\\u062A\\u0643 \\u0634\\u0641\\u062A \\u0646\\u0633\\u062E\\u0629 \\u0645\\u0646\\u064A \\u0643\\u0627\\u0646 \\u0639\\u0646\\u062F\\u0647\\u0627 \\u0648\\u0642\\u062A \\u0623\\u0643\\u062A\\u0631."
t["I woke up ready to take something back."] = "\\u0641\\u0642\\u062A \\u0648\\u0623\\u0646\\u0627 \\u062C\\u0627\\u0647\\u0632\\u0629 \\u0627\\u0633\\u062A\\u0631\\u062C\\u0639 \\u0634\\u064A."
t["I won't die because you can't stop swinging!"] = "\\u0645\\u0627 \\u0631\\u062D \\u0645\\u0648\\u062A \\u0644\\u0623\\u0646\\u0643 \\u0645\\u0627 \\u0641\\u064A\\u0643 \\u062A\\u0648\\u0642\\u0641 \\u0636\\u0631\\u0628!"
t["I won't fall for that twice."] = "\\u0645\\u0627 \\u0631\\u062D \\u062A\\u0636\\u062D\\u0643 \\u0639\\u0644\\u064A\\u0651 \\u0645\\u0631\\u062A\\u064A\\u0646."
t["I won't finish you. Stay away from me."] = "\\u0645\\u0627 \\u0631\\u062D \\u0627\\u062E\\u0644\\u0635 \\u0639\\u0644\\u064A\\u0643. \\u0627\\u0628\\u0639\\u062F \\u0639\\u0646\\u064A."
t["I won't give it an easy body to inherit."] = "\\u0645\\u0627 \\u0631\\u062D \\u062E\\u0644\\u064A\\u0647 \\u064A\\u0648\\u0631\\u062B \\u062C\\u0633\\u0645 \\u0628\\u0627\\u0644\\u0633\\u0627\\u0647\\u0644."
t["I won't last through that in this condition."] = "\\u0645\\u0648 \\u0631\\u062D \\u0643\\u0645\\u0644 \\u0647\\u064A\\u0643 \\u0628\\u0647\\u0627\\u0644\\u062D\\u0627\\u0644\\u0629."
t["I won't let it reach you!"] = "\\u0645\\u0627 \\u0631\\u062D \\u062E\\u0644\\u064A\\u0647 \\u064A\\u0648\\u0635\\u0644\\u0643!"
t["I won't let you beat me for free."] = "\\u0645\\u0627 \\u0631\\u062D \\u062E\\u0644\\u064A\\u0643 \\u062A\\u0636\\u0631\\u0628\\u0646\\u064A \\u0628\\u0628\\u0644\\u0627\\u0634."
t["I won't make you drag me out of that crowd."] = "\\u0645\\u0648 \\u0631\\u062D \\u062E\\u0644\\u064A\\u0643 \\u062A\\u0633\\u062D\\u0628\\u0646\\u064A \\u0645\\u0646 \\u0647\\u0627\\u0644\\u0632\\u062D\\u0645\\u0629."
t["I won't stand here and take it!"] = "\\u0645\\u0627 \\u0631\\u062D \\u0636\\u0644 \\u0648\\u0627\\u0642\\u0641\\u0629 \\u0648\\u0622\\u0643\\u0644!"
t["I won't stand in your way again. Or near it."] = "\\u0645\\u0627 \\u0631\\u062D \\u0648\\u0642\\u0641 \\u0628\\u0637\\u0631\\u064A\\u0642\\u0643 \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629. \\u0648\\u0644\\u0627 \\u062C\\u0646\\u0628\\u0647\\u0627."
t["I won't strike again unless you do."] = "\\u0645\\u0627 \\u0631\\u062D \\u0627\\u0636\\u0631\\u0628 \\u0625\\u0644\\u0627 \\u0625\\u0630\\u0627 \\u0625\\u0646\\u062A \\u0636\\u0631\\u0628\\u062A."
t["I won't tell them. But I'm watching you."] = "\\u0645\\u0627 \\u0631\\u062D \\u062E\\u0628\\u0631\\u0647\\u0646. \\u0628\\u0633 \\u0639\\u064A\\u0646\\u064A \\u0639\\u0644\\u064A\\u0643."
t["I won't turn my back on you again."] = "\\u0645\\u0627 \\u0631\\u062D \\u0639\\u0637\\u064A\\u0643 \\u0636\\u0647\\u0631\\u064A \\u0645\\u0631\\u0629 \\u062A\\u0627\\u0646\\u064A\\u0629."
t["I wonder how long this station kept broadcasting."] = "\\u064A\\u0627 \\u062A\\u0631\\u0649 \\u0644\\u0623\\u064A\\u0645\\u062A\\u0649 \\u0636\\u0644\\u062A \\u0647\\u0627\\u0644\\u0645\\u062D\\u0637\\u0629 \\u062A\\u0628\\u062B\\u061F"
t["I wonder if some part of it knew. I hope not."] = "\\u0628\\u0633\\u0623\\u0644 \\u0625\\u0630\\u0627 \\u062C\\u0632\\u0621 \\u0645\\u0646\\u0647 \\u0643\\u0627\\u0646 \\u0639\\u0627\\u0631\\u0641. \\u0628\\u062A\\u0645\\u0646\\u0649 \\u0644\\u0623."
t["I wonder where they are broadcasting from."] = "\\u064A\\u0627 \\u062A\\u0631\\u0649 \\u0645\\u0646 \\u0648\\u064A\\u0646 \\u0639\\u0645 \\u064A\\u0628\\u062B\\u0648\\u0627\\u061F"
t["I wonder which of them said the last good morning in Kentucky."] = "\\u0628\\u0633\\u0623\\u0644 \\u0645\\u064A\\u0646 \\u0645\\u0646\\u0647\\u0645 \\u0642\\u0627\\u0644 \\u0622\\u062E\\u0631 \\u0635\\u0628\\u0627\\u062D \\u0627\\u0644\\u062E\\u064A\\u0631 \\u0628\\u0643\\u0646\\u062A\\u0627\\u0643\\u064A."
t["I worked fryers for three summers. I can still hear the timer."] = "\\u0627\\u0634\\u062A\\u063A\\u0644\\u062A \\u0639\\u0627\\u0644\\u0642\\u0644\\u0627\\u064A\\u0627\\u062A \\u062A\\u0644\\u0627\\u062A \\u0635\\u064A\\u0641\\u064A\\u0627\\u062A. \\u0644\\u0633\\u0627 \\u0628\\u0633\\u0645\\u0639 \\u0627\\u0644\\u0645\\u0624\\u0642\\u062A."
t["I would feel better if we kept two clean bandages ready."] = "\\u0628\\u0631\\u062A\\u0627\\u062D \\u0623\\u0643\\u062A\\u0631 \\u0625\\u0630\\u0627 \\u0636\\u0644 \\u0639\\u0646\\u0627 \\u0636\\u0645\\u0627\\u062F\\u062A\\u064A\\u0646 \\u0646\\u0636\\u0627\\u0641 \\u062C\\u0627\\u0647\\u0632\\u064A\\u0646."
t["I would keep the warning and question the certainty."] = "\\u0643\\u0646\\u062A \\u062E\\u0644\\u064A \\u0627\\u0644\\u062A\\u062D\\u0630\\u064A\\u0631 \\u0648\\u0634\\u0643\\u0643 \\u0628\\u0627\\u0644\\u064A\\u0642\\u064A\\u0646."
t["I would like to find something worth reading when things are quiet."] = "\\u0628\\u062F\\u064A \\u0644\\u0627\\u0642\\u064A \\u0634\\u064A \\u064A\\u0633\\u062A\\u0627\\u0647\\u0644 \\u0627\\u0644\\u0642\\u0631\\u0627\\u0621\\u0629 \\u0644\\u0645\\u0627 \\u062A\\u0647\\u062F\\u0649 \\u0627\\u0644\\u0623\\u0645\\u0648\\u0631."
t["I would rather arrive late than walk blind into a room."] = "\\u0628\\u0648\\u0635\\u0644 \\u0645\\u062A\\u0623\\u062E\\u0631\\u0629 \\u0623\\u062D\\u0633\\u0646 \\u0645\\u0627 \\u0641\\u0648\\u062A \\u0639\\u063A\\u0631\\u0641\\u0629 \\u0639\\u0627\\u0644\\u0639\\u0645\\u064A\\u0627\\u0646\\u064A."
t["I would rather have the argument than bury the mistake."] = "\\u0628\\u0641\\u0636\\u0651\\u0644 \\u0627\\u0644\\u062E\\u0646\\u0627\\u0642\\u0629 \\u0639\\u0644\\u0649 \\u0625\\u0646\\u0646\\u0627 \\u0646\\u062F\\u0641\\u0646 \\u0627\\u0644\\u063A\\u0644\\u0637\\u0629."
