t["If I reach for you afterward, don't hesitate."] = "\\u0625\\u0630\\u0627 \\u0645\\u062F\\u064A\\u062A \\u0625\\u064A\\u062F\\u064A \\u0639\\u0644\\u064A\\u0643 \\u0628\\u0639\\u062F\\u064A\\u0646, \\u0644\\u0627 \\u062A\\u062A\\u0631\\u062F\\u062F."
t["If I say your name after I turn, please know it is only an echo."] = "\\u0625\\u0630\\u0627 \\u0642\\u0644\\u062A \\u0627\\u0633\\u0645\\u0643 \\u0628\\u0639\\u062F \\u0645\\u0627 \\u0627\\u062A\\u062D\\u0648\\u0644, \\u0627\\u0639\\u0631\\u0641 \\u0625\\u0646\\u0647 \\u0628\\u0633 \\u0635\\u062F\\u0649."
t["If I sit still long enough, maybe the world forgets me too."] = "\\u0625\\u0630\\u0627 \\u0642\\u0639\\u062F\\u062A \\u0633\\u0627\\u0643\\u062A\\u0629 \\u0643\\u0641\\u0627\\u064A\\u0629\\u060C \\u064A\\u0645\\u0643\\u0646 \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u062A\\u0646\\u0633\\u0627\\u0646\\u064A \\u0643\\u0645\\u0627\\u0646."
t["If I turn, shoot me quick. Don't make a goddamn speech."] = "\\u0625\\u0630\\u0627 \\u062A\\u062D\\u0648\\u0644\\u062A\\u060C \\u0637\\u062E\\u0646\\u064A \\u0628\\u0633\\u0631\\u0639\\u0629. \\u0628\\u0644\\u0627 \\u062E\\u0637\\u0628\\u0629 \\u064A\\u0644\\u0639\\u0646\\u0647\\u0627."
t["If I turn, shoot me quick. Don't make a speech."] = "\\u0625\\u0630\\u0627 \\u062A\\u062D\\u0648\\u0644\\u062A\\u060C \\u0637\\u062E\\u0646\\u064A \\u0628\\u0633\\u0631\\u0639\\u0629. \\u0628\\u0644\\u0627 \\u062E\\u0637\\u0628\\u0629."
t["If I yell from up here, the whole county hears. Tempting. No."] = "\\u0625\\u0630\\u0627 \\u0635\\u0631\\u062E\\u062A \\u0645\\u0646 \\u0647\\u0648\\u0646\\u060C \\u0627\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u0643\\u0644\\u0647\\u0627 \\u0628\\u062A\\u0633\\u0645\\u0639. \\u0645\\u063A\\u0631\\u064A. \\u0644\\u0623."
t["If a billboard still promises tomorrow, that's bold of it."] = "\\u0625\\u0630\\u0627 \\u0644\\u0633\\u0627 \\u0641\\u064A \\u0644\\u0648\\u062D\\u0629 \\u0625\\u0639\\u0644\\u0627\\u0646\\u0627\\u062A \\u0628\\u062A\\u0648\\u0639\\u062F \\u0628\\u0628\\u0643\\u0631\\u0627\\u060C \\u064A\\u0627 \\u0639\\u064A\\u0646\\u064A \\u0639\\u0627\\u0644\\u062C\\u0631\\u0623\\u0629."
t["If a book changes how I act tomorrow, did it save a piece of the world?"] = "\\u0625\\u0630\\u0627 \\u0643\\u062A\\u0627\\u0628 \\u063A\\u064A\\u0631 \\u062A\\u0635\\u0631\\u0641\\u064A \\u0628\\u0643\\u0631\\u0627\\u060C \\u0628\\u064A\\u0643\\u0648\\u0646 \\u0646\\u0642\\u0630 \\u062D\\u062A\\u0629 \\u0645\\u0646 \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627\\u061F"
t["If a horse looks out of a barn, I'm stopping to say hello."] = "\\u0625\\u0630\\u0627 \\u0637\\u0644\\u0651 \\u062D\\u0635\\u0627\\u0646 \\u0645\\u0646 \\u0627\\u0633\\u0637\\u0628\\u0644\\u060C \\u0631\\u062D \\u0648\\u0642\\u0641 \\u0633\\u0644\\u0651\\u0645 \\u0639\\u0644\\u064A\\u0647."
t["If a step is missing, write it in the margin, %1."] = "\\u0625\\u0630\\u0627 \\u0641\\u064A \\u062E\\u0637\\u0648\\u0629 \\u0646\\u0627\\u0642\\u0635\\u0629\\u060C \\u0627\\u0643\\u062A\\u0628\\u0647\\u0627 \\u0639\\u0627\\u0644\\u0647\\u0627\\u0645\\u0634 \\u064A\\u0627 %1."
t["If anyone asks, I found a spa in Knox County."] = "\\u0625\\u0630\\u0627 \\u062D\\u062F\\u0627 \\u0633\\u0623\\u0644\\u060C \\u0644\\u0642\\u064A\\u062A \\u0633\\u0628\\u0627 \\u0628\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u0646\\u0648\\u0643\\u0633."
t["If anyone asks, I was checking the perimeter."] = "\\u0625\\u0630\\u0627 \\u062D\\u062F\\u0627 \\u0633\\u0623\\u0644\\u060C \\u0643\\u0646\\u062A \\u0639\\u0645 \\u0634\\u064A\\u0643 \\u0627\\u0644\\u0645\\u062D\\u064A\\u0637."
t["If anyone's still taking prayers, I have a list."] = "\\u0625\\u0630\\u0627 \\u0644\\u0633\\u0627 \\u062D\\u062F\\u0627 \\u0639\\u0645 \\u064A\\u0633\\u062A\\u0642\\u0628\\u0644 \\u0635\\u0644\\u0648\\u0627\\u062A\\u060C \\u0639\\u0646\\u062F\\u064A \\u0642\\u0627\\u0626\\u0645\\u0629."
t["If everything stays in its place, maybe I can too."] = "\\u0625\\u0630\\u0627 \\u0643\\u0644 \\u0634\\u064A \\u0636\\u0644 \\u0628\\u0645\\u062D\\u0644\\u0647\\u060C \\u064A\\u0645\\u0643\\u0646 \\u0623\\u0646\\u0627 \\u0643\\u0645\\u0627\\u0646."
t["If fear made every choice for me, I'd still be behind the first locked door."] = "\\u0644\\u0648 \\u0627\\u0644\\u062E\\u0648\\u0641 \\u0627\\u062E\\u062A\\u0627\\u0631 \\u0639\\u0646\\u064A \\u0643\\u0644 \\u0634\\u064A\\u060C \\u0643\\u0646\\u062A \\u0644\\u0633\\u0627 \\u0648\\u0631\\u0627 \\u0623\\u0648\\u0644 \\u0628\\u0627\\u0628 \\u0645\\u0642\\u0641\\u0648\\u0644."
t["If it stops creaking, then I'll worry."] = "\\u0625\\u0630\\u0627 \\u0628\\u0637\\u0651\\u0644\\u062A \\u062A\\u0637\\u0642\\u0637\\u0642\\u060C \\u0633\\u0627\\u0639\\u062A\\u0647\\u0627 \\u0628\\u0642\\u0644\\u0642."
t["If it were me, I'd want you to stay. So I'm staying."] = "\\u0644\\u0648 \\u0643\\u0646\\u062A \\u0623\\u0646\\u0627\\u060C \\u0643\\u0646\\u062A \\u0628\\u062F\\u064A \\u064A\\u0627\\u0643 \\u062A\\u0636\\u0644. \\u0641\\u0623\\u0646\\u0627 \\u0628\\u0627\\u0642\\u064A\\u0629."
t["If my weapon breaks in there, you have to come get me."] = "\\u0625\\u0630\\u0627 \\u0627\\u0646\\u0643\\u0633\\u0631 \\u0633\\u0644\\u0627\\u062D\\u064A \\u062C\\u0648\\u0627\\u060C \\u0644\\u0627\\u0632\\u0645 \\u062A\\u062C\\u064A \\u062A\\u0627\\u062E\\u062F\\u0646\\u064A."
t["If one trips in the woods and nobody hears it, it still gets up."] = "\\u0625\\u0630\\u0627 \\u0648\\u0627\\u062D\\u062F \\u062A\\u0639\\u062A\\u0631 \\u0628\\u0627\\u0644\\u063A\\u0627\\u0628\\u0629 \\u0648\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0633\\u0645\\u0639\\u060C \\u0628\\u0631\\u0636\\u0648 \\u0628\\u064A\\u0642\\u0648\\u0645."
t["If patience fed people, we'd have a full pantry."] = "\\u0644\\u0648 \\u0627\\u0644\\u0635\\u0628\\u0631 \\u0628\\u064A\\u0637\\u0639\\u0645\\u064A\\u060C \\u0643\\u0627\\u0646 \\u0645\\u062E\\u0632\\u0646\\u0646\\u0627 \\u0645\\u0644\\u064A\\u0627\\u0646."
t["If someone scores this, I want points for distance."] = "\\u0625\\u0630\\u0627 \\u062D\\u062F\\u0627 \\u0639\\u0645 \\u064A\\u062D\\u0633\\u0628 \\u0639\\u0644\\u0627\\u0645\\u0627\\u062A\\u060C \\u0628\\u062F\\u064A \\u0646\\u0642\\u0627\\u0637 \\u0639\\u0627\\u0644\\u0645\\u0633\\u0627\\u0641\\u0629."
t["If something comes, I'm the first story. Short story."] = "\\u0625\\u0630\\u0627 \\u0625\\u062C\\u0627 \\u0634\\u064A\\u060C \\u0623\\u0646\\u0627 \\u0623\\u0648\\u0644 \\u0642\\u0635\\u0629. \\u0642\\u0635\\u0629 \\u0642\\u0635\\u064A\\u0631\\u0629."
t["If that is your decision, I'll go."] = "\\u0625\\u0630\\u0627 \\u0647\\u064A\\u0643 \\u0642\\u0631\\u0627\\u0631\\u0643\\u060C \\u0628\\u0645\\u0634\\u064A."
t["If that were me, I would have left five minutes ago."] = "\\u0644\\u0648 \\u0623\\u0646\\u0627 \\u0645\\u062D\\u0644\\u0647\\u0645\\u060C \\u0643\\u0646\\u062A \\u0637\\u0644\\u0639\\u062A \\u0645\\u0646 \\u062E\\u0645\\u0633 \\u062F\\u0642\\u0627\\u064A\\u0642."
t["If the army couldn't hold Knox, I'm not sure a shelf of helmets will."] = "\\u0625\\u0630\\u0627 \\u0627\\u0644\\u062C\\u064A\\u0634 \\u0645\\u0627 \\u0642\\u062F\\u0631 \\u064A\\u0645\\u0633\\u0643 \\u0646\\u0648\\u0643\\u0633\\u060C \\u0645\\u0627 \\u0628\\u0638\\u0646 \\u0631\\u0641 \\u062E\\u0648\\u0630 \\u0631\\u062D \\u064A\\u0642\\u062F\\u0631."
t["If the church bell rings, it wasn't me."] = "\\u0625\\u0630\\u0627 \\u062F\\u0642 \\u062C\\u0631\\u0633 \\u0627\\u0644\\u0643\\u0646\\u064A\\u0633\\u0629\\u060C \\u0645\\u0648 \\u0623\\u0646\\u0627."
t["If the county line could talk, it'd tell us to run..."] = "\\u0644\\u0648 \\u062D\\u0643\\u064A\\u062A \\u062D\\u062F\\u0648\\u062F \\u0627\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629\\u060C \\u0644\\u0642\\u0627\\u0644\\u062A\\u0644\\u0646\\u0627 \\u0627\\u0647\\u0631\\u0628\\u0648\\u0627..."
t["If the ending cheats, read me the middle instead."] = "\\u0625\\u0630\\u0627 \\u0627\\u0644\\u0646\\u0647\\u0627\\u064A\\u0629 \\u063A\\u0634\\u0627\\u0634\\u0629\\u060C \\u0627\\u0642\\u0631\\u0627\\u0644\\u064A \\u0627\\u0644\\u0646\\u0635 \\u0623\\u062D\\u0633\\u0646."
t["If the ground drinks enough, maybe the garden will too."] = "\\u0625\\u0630\\u0627 \\u0627\\u0644\\u0623\\u0631\\u0636 \\u0634\\u0631\\u0628\\u062A \\u0643\\u0641\\u0627\\u064A\\u0629\\u060C \\u064A\\u0645\\u0643\\u0646 \\u0627\\u0644\\u062C\\u0646\\u064A\\u0646\\u0629 \\u062A\\u0634\\u0631\\u0628 \\u0643\\u0645\\u0627\\u0646."
t["If the pipes knock, I'm leaving."] = "\\u0625\\u0630\\u0627 \\u0627\\u0644\\u0645\\u0648\\u0627\\u0633\\u064A\\u0631 \\u062F\\u0642\\u062A\\u060C \\u0623\\u0646\\u0627 \\u0637\\u0627\\u0644\\u0639\\u0629."
t["If the road's clear tomorrow, what do we need most?"] = "\\u0625\\u0630\\u0627 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642 \\u0641\\u0627\\u0636\\u064A \\u0628\\u0643\\u0631\\u0627\\u060C \\u0634\\u0648 \\u0623\\u0643\\u062A\\u0631 \\u0634\\u064A \\u0645\\u062D\\u062A\\u0627\\u062C\\u064A\\u0646\\u0647\\u061F"
t["If the roof starts leaking, do we have a better plan than a bucket?"] = "\\u0625\\u0630\\u0627 \\u0628\\u0644\\u0651\\u0634 \\u0627\\u0644\\u0633\\u0642\\u0641 \\u064A\\u0646\\u0642\\u0637\\u060C \\u0639\\u0646\\u0627 \\u062E\\u0637\\u0629 \\u0623\\u062D\\u0633\\u0646 \\u0645\\u0646 \\u0627\\u0644\\u0633\\u0637\\u0644\\u061F"
t["If the shutters hold, I can almost sleep to it."] = "\\u0625\\u0630\\u0627 \\u0635\\u0645\\u062F\\u062A \\u0627\\u0644\\u062F\\u0631\\u0641\\u060C \\u064A\\u0645\\u0643\\u0646 \\u0646\\u0627\\u0645 \\u0639\\u0644\\u0649 \\u0635\\u0648\\u062A\\u0647."
t["If the water stops, I stop. Fair deal."] = "\\u0625\\u0630\\u0627 \\u0627\\u0644\\u0645\\u064A \\u0648\\u0642\\u0641\\u062A\\u060C \\u0628\\u0648\\u0642\\u0641. \\u0627\\u062A\\u0641\\u0627\\u0642 \\u0639\\u0627\\u062F\\u0644."
t["If the woods judge me, they can file a report."] = "\\u0625\\u0630\\u0627 \\u0627\\u0644\\u063A\\u0627\\u0628\\u0629 \\u0628\\u062F\\u0647\\u0627 \\u062A\\u062D\\u0643\\u0645 \\u0639\\u0644\\u064A\\u0651\\u060C \\u062A\\u0642\\u062F\\u0645 \\u0634\\u0643\\u0648\\u0649."
t["If the world ends, at least it ended here."] = "\\u0625\\u0630\\u0627 \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627 \\u062E\\u0644\\u0635\\u062A\\u060C \\u0639\\u0627\\u0644\\u0623\\u0642\\u0644 \\u062E\\u0644\\u0635\\u062A \\u0647\\u0648\\u0646."
t["If there is a monster in there, I am bringing it home."] = "\\u0625\\u0630\\u0627 \\u0641\\u064A \\u0648\\u062D\\u0634 \\u062C\\u0648\\u0627\\u060C \\u0631\\u062D \\u062C\\u064A\\u0628\\u0647 \\u0639\\u0627\\u0644\\u0628\\u064A\\u062A."
t["If there is somewhere after this, I'll wait for you - but not soon."] = "\\u0625\\u0630\\u0627 \\u0641\\u064A \\u0634\\u064A \\u0628\\u0639\\u062F \\u0647\\u064A\\u0643, \\u0631\\u062D \\u0627\\u0633\\u062A\\u0646\\u0627\\u0643 - \\u0628\\u0633 \\u0645\\u0648 \\u0642\\u0631\\u064A\\u0628."
t["If there's a collection plate, it's the only thing in Kentucky still full."] = "\\u0625\\u0630\\u0627 \\u0641\\u064A \\u0635\\u062D\\u0646 \\u062A\\u0628\\u0631\\u0639\\u0627\\u062A\\u060C \\u0641\\u0647\\u0648 \\u0627\\u0644\\u0634\\u064A \\u0627\\u0644\\u0648\\u062D\\u064A\\u062F \\u0627\\u0644\\u0645\\u0644\\u064A\\u0627\\u0646 \\u0628\\u0643\\u0646\\u062A\\u0627\\u0643\\u064A."
t["If there's a working battery in here, I want it."] = "\\u0625\\u0630\\u0627 \\u0641\\u064A \\u0628\\u0637\\u0627\\u0631\\u064A\\u0629 \\u0634\\u063A\\u0627\\u0644\\u0629 \\u0647\\u0648\\u0646\\u060C \\u0628\\u062F\\u064A \\u064A\\u0627\\u0647\\u0627."
t["If there's coffee left in the pot, nobody's been brave enough to try it."] = "\\u0625\\u0630\\u0627 \\u0644\\u0633\\u0627 \\u0641\\u064A \\u0642\\u0647\\u0648\\u0629 \\u0628\\u0627\\u0644\\u0625\\u0628\\u0631\\u064A\\u0642\\u060C \\u0641\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u062A\\u062C\\u0631\\u0623 \\u064A\\u062C\\u0631\\u0628\\u0647\\u0627."
t["If there's news out there, this is where it will find us."] = "\\u0625\\u0630\\u0627 \\u0641\\u064A \\u0623\\u062E\\u0628\\u0627\\u0631 \\u0628\\u0631\\u0627\\u060C \\u0647\\u0648\\u0646 \\u0631\\u062D \\u062A\\u0644\\u0627\\u0642\\u064A\\u0646\\u0627."
t["If there's trouble outside, I'd rather check it in daylight."] = "\\u0625\\u0630\\u0627 \\u0641\\u064A \\u0645\\u0634\\u0643\\u0644\\u0629 \\u0628\\u0631\\u0627\\u060C \\u0628\\u0641\\u0636\\u0644 \\u0634\\u0648\\u0641\\u0647\\u0627 \\u0628\\u0627\\u0644\\u0646\\u0647\\u0627\\u0631."
t["If things go bad, I know you will still be there."] = "\\u0625\\u0630\\u0627 \\u062E\\u0631\\u0628\\u062A \\u0627\\u0644\\u062F\\u0646\\u064A\\u0627\\u060C \\u0628\\u0639\\u0631\\u0641 \\u0625\\u0646\\u0643 \\u0631\\u062D \\u062A\\u0636\\u0644 \\u062C\\u0646\\u0628\\u064A."
t["If this ends tomorrow, I sleep until next week."] = "\\u0625\\u0630\\u0627 \\u062E\\u0644\\u0635 \\u0628\\u0643\\u0631\\u0627\\u060C \\u0628\\u0646\\u0627\\u0645 \\u0644\\u062C\\u0645\\u0639\\u0629 \\u0627\\u0644\\u062C\\u0627\\u064A\\u0629."
t["If this gnome tells anyone, I'll deny it."] = "\\u0625\\u0630\\u0627 \\u0647\\u0627\\u0644\\u0642\\u0632\\u0645 \\u062E\\u0628\\u0631 \\u062D\\u062F\\u0627\\u060C \\u0628\\u0646\\u0643\\u0631."
t["If this holds, dinner is sorted."] = "\\u0625\\u0630\\u0627 \\u0635\\u0645\\u062F\\u060C \\u0627\\u0644\\u0639\\u0634\\u0627 \\u0645\\u0636\\u0645\\u0648\\u0646."
t["If this takes any longer, name the river after me."] = "\\u0625\\u0630\\u0627 \\u0637\\u0648\\u0644\\u062A \\u0623\\u0643\\u062A\\u0631\\u060C \\u0633\\u0645\\u0648\\u0627 \\u0627\\u0644\\u0646\\u0647\\u0631 \\u0628\\u0627\\u0633\\u0645\\u064A."
t["If we can eat this, we've already lost."] = "\\u0625\\u0630\\u0627 \\u0635\\u0631\\u0646\\u0627 \\u0646\\u0627\\u0643\\u0644 \\u0647\\u0627\\u062F\\u060C \\u064A\\u0639\\u0646\\u064A \\u062E\\u0633\\u0631\\u0646\\u0627 \\u0645\\u0646 \\u0632\\u0645\\u0627\\u0646."
t["If we can't change our minds, we aren't really watching."] = "\\u0625\\u0630\\u0627 \\u0645\\u0627 \\u0641\\u064A\\u0646\\u0627 \\u0646\\u063A\\u064A\\u0631 \\u0631\\u0623\\u064A\\u0646\\u0627\\u060C \\u0641\\u0646\\u062D\\u0646\\u0627 \\u0645\\u0648 \\u0639\\u0645 \\u0646\\u0646\\u062A\\u0628\\u0647 \\u0639\\u0646 \\u062C\\u062F."
t["If we cannot find %1 soon, this house is in trouble."] = "\\u0625\\u0630\\u0627 \\u0645\\u0627 \\u0644\\u0642\\u064A\\u0646\\u0627 %1 \\u0642\\u0631\\u064A\\u0628\\u060C \\u0647\\u0627\\u0644\\u0628\\u064A\\u062A \\u0628\\u0645\\u0635\\u064A\\u0628\\u0629."
t["If we could cook one proper meal, what would you ask for, %1?"] = "\\u0644\\u0648 \\u0641\\u064A\\u0646\\u0627 \\u0646\\u0637\\u0628\\u062E \\u0623\\u0643\\u0644\\u0629 \\u0639\\u0646 \\u062C\\u062F\\u060C \\u0634\\u0648 \\u0628\\u062A\\u0637\\u0644\\u0628 \\u064A\\u0627 %1\\u061F"
t["If we die here, some bastard just loots this place. Like we did."] = "\\u0625\\u0630\\u0627 \\u0645\\u062A\\u0646\\u0627 \\u0647\\u0648\\u0646\\u060C \\u0634\\u064A \\u0627\\u0628\\u0646 \\u0643\\u0644\\u0628 \\u0628\\u064A\\u0646\\u0647\\u0628 \\u0627\\u0644\\u0645\\u062D\\u0644. \\u0645\\u062A\\u0644 \\u0645\\u0627 \\u0639\\u0645\\u0644\\u0646\\u0627."
t["If we die here, this place is just somebody else's loot."] = "\\u0625\\u0630\\u0627 \\u0645\\u062A\\u0646\\u0627 \\u0647\\u0648\\u0646\\u060C \\u0647\\u0627\\u0644\\u0645\\u062D\\u0644 \\u0628\\u064A\\u0635\\u064A\\u0631 \\u063A\\u0646\\u064A\\u0645\\u0629 \\u0644\\u063A\\u064A\\u0631\\u0646\\u0627."
t["If we ever find a diner again, I'll buy the bad coffee."] = "\\u0625\\u0630\\u0627 \\u0644\\u0642\\u064A\\u0646\\u0627 \\u0645\\u0637\\u0639\\u0645 \\u064A\\u0648\\u0645\\u064B\\u0627 \\u0645\\u0627\\u060C \\u0639\\u0644\\u064A\\u064A \\u0627\\u0644\\u0642\\u0647\\u0648\\u0629 \\u0627\\u0644\\u0639\\u0627\\u0637\\u0644\\u0629."
t["If we find cigarettes, save me one. I'll share the rest."] = "\\u0625\\u0630\\u0627 \\u0644\\u0642\\u064A\\u0646\\u0627 \\u062F\\u062E\\u0627\\u0646\\u060C \\u062E\\u0644\\u064A\\u0644\\u064A \\u0648\\u062D\\u062F\\u0629. \\u0648\\u0627\\u0644\\u0628\\u0627\\u0642\\u064A \\u0628\\u0634\\u0627\\u0631\\u0643\\u0643 \\u0641\\u064A\\u0647."
t["If we find coffee, I'm calling this a victory."] = "\\u0625\\u0630\\u0627 \\u0644\\u0642\\u064A\\u0646\\u0627 \\u0642\\u0647\\u0648\\u0629\\u060C \\u0628\\u0639\\u062A\\u0628\\u0631\\u0647\\u0627 \\u0627\\u0646\\u062A\\u0635\\u0627\\u0631."
t["If we get a quiet minute, I'd like to eat with you."] = "\\u0625\\u0630\\u0627 \\u0635\\u0627\\u0631 \\u0645\\u0639\\u0646\\u0627 \\u062F\\u0642\\u064A\\u0642\\u0629 \\u0647\\u062F\\u0648\\u0621\\u060C \\u0628\\u062F\\u064A \\u0622\\u0643\\u0644 \\u0645\\u0639\\u0643."
t["If we see anything worth reading, I would like to bring it home."] = "\\u0625\\u0630\\u0627 \\u0634\\u0641\\u0646\\u0627 \\u0634\\u064A \\u0628\\u064A\\u0646\\u0642\\u0631\\u0627\\u060C \\u0628\\u062F\\u064A \\u0646\\u0627\\u062E\\u062F\\u0647 \\u0639\\u0627\\u0644\\u0628\\u064A\\u062A."
t["If we're staying, I could be checking the doors."] = "\\u0625\\u0630\\u0627 \\u0628\\u0627\\u0642\\u064A\\u064A\\u0646\\u060C \\u0643\\u0627\\u0646 \\u0641\\u064A\\u0646\\u064A \\u0627\\u062A\\u0641\\u0642\\u062F \\u0627\\u0644\\u0628\\u0648\\u0627\\u0628."
t["If we're waiting, I'm getting my reps in."] = "\\u0625\\u0630\\u0627 \\u0645\\u0633\\u062A\\u0646\\u064A\\u064A\\u0646\\u060C \\u0631\\u062D \\u0627\\u0639\\u0645\\u0644 \\u062A\\u0645\\u0627\\u0631\\u064A\\u0646\\u064A."
t["If we're waiting, I'm getting my reps in. In my head."] = "\\u0625\\u0630\\u0627 \\u0645\\u0633\\u062A\\u0646\\u064A\\u064A\\u0646\\u060C \\u0631\\u062D \\u0627\\u0639\\u0645\\u0644 \\u062A\\u0645\\u0627\\u0631\\u064A\\u0646\\u064A. \\u0628\\u0631\\u0627\\u0633\\u064A."
t["If you find cigarettes, save me one."] = "\\u0625\\u0630\\u0627 \\u0644\\u0642\\u064A\\u062A \\u062F\\u062E\\u0627\\u0646\\u060C \\u062E\\u0644\\u064A\\u0644\\u064A \\u0648\\u062D\\u062F\\u0629."
t["If you hear a branch snap, say something."] = "\\u0625\\u0630\\u0627 \\u0633\\u0645\\u0639\\u062A \\u063A\\u0635\\u0646 \\u0627\\u0646\\u0643\\u0633\\u0631\\u060C \\u0627\\u062D\\u0643\\u064A."
t["If you hear me, tap back. No need to shout."] = "\\u0625\\u0630\\u0627 \\u0633\\u0627\\u0645\\u0639\\u0646\\u064A\\u060C \\u0627\\u0646\\u0642\\u0631 \\u0646\\u0642\\u0631\\u0629. \\u0645\\u0627 \\u0641\\u064A \\u062F\\u0627\\u0639\\u064A \\u0644\\u0644\\u0635\\u0631\\u064A\\u062E."
t["If you need a minute, take it. I'll complain quietly."] = "\\u0625\\u0630\\u0627 \\u0628\\u062F\\u0643 \\u062F\\u0642\\u064A\\u0642\\u0629\\u060C \\u062E\\u0648\\u062F\\u0647\\u0627. \\u0631\\u062D \\u0627\\u062A\\u0630\\u0645\\u0631 \\u0628\\u0647\\u062F\\u0648\\u0621."
t["If you see a pack, remember me. This is getting rough."] = "\\u0625\\u0630\\u0627 \\u0634\\u0641\\u062A \\u0628\\u0627\\u0643\\u064A\\u062A\\u060C \\u062A\\u0630\\u0643\\u0631\\u0646\\u064A. \\u0627\\u0644\\u0648\\u0636\\u0639 \\u0639\\u0645 \\u064A\\u0635\\u0639\\u0628."
t["If you turn at night and nobody knew, that's on both of us."] = "\\u0625\\u0630\\u0627 \\u062A\\u062D\\u0648\\u0644\\u062A \\u0628\\u0627\\u0644\\u0644\\u064A\\u0644 \\u0648\\u0645\\u0627 \\u062D\\u062F\\u0627 \\u0639\\u0627\\u0631\\u0641\\u060C \\u0627\\u0644\\u0630\\u0646\\u0628 \\u0639\\u0644\\u064A\\u0646\\u0627 \\u0646\\u062D\\u0646\\u0627 \\u0627\\u0644\\u062A\\u0646\\u064A\\u0646."
t["If you're waiting for a sign, this is it. It says 'beans'."] = "\\u0625\\u0630\\u0627 \\u0645\\u0633\\u062A\\u0646\\u064A \\u0625\\u0634\\u0627\\u0631\\u0629\\u060C \\u0647\\u064A \\u0647\\u064A. \\u0645\\u0643\\u062A\\u0648\\u0628 \\u0639\\u0644\\u064A\\u0647\\u0627 \\u0641\\u0627\\u0635\\u0648\\u0644\\u064A\\u0627."
t["Ignoring this is how a bad call kills us later."] = "\\u0627\\u0644\\u062A\\u0637\\u0646\\u064A\\u0634 \\u0647\\u064A\\u0643 \\u0628\\u064A\\u062E\\u0644\\u064A \\u0642\\u0631\\u0627\\u0631 \\u063A\\u0644\\u0637 \\u064A\\u0642\\u062A\\u0644\\u0646\\u0627 \\u0628\\u0639\\u062F\\u064A\\u0646."
t["Illness in the house. Visiting is a poor idea."] = "\\u0645\\u0631\\u0636 \\u0628\\u0627\\u0644\\u0628\\u064A\\u062A. \\u0627\\u0644\\u0632\\u064A\\u0627\\u0631\\u0629 \\u0641\\u0643\\u0631\\u0629 \\u0639\\u0627\\u0637\\u0644\\u0629."
t["Imagine explaining this camp to someone from 1992."] = "\\u062A\\u062E\\u064A\\u0644 \\u062A\\u0634\\u0631\\u062D \\u0647\\u0627\\u0644\\u0645\\u062E\\u064A\\u0645 \\u0644\\u062D\\u062F\\u0627 \\u0645\\u0646 1992."
t["Imagine one of them stops, checks a watch, and keeps going."] = "\\u062A\\u062E\\u064A\\u0644 \\u0648\\u0627\\u062D\\u062F \\u0645\\u0646\\u0647\\u0645 \\u064A\\u0648\\u0642\\u0641\\u060C \\u064A\\u0634\\u0648\\u0641 \\u0633\\u0627\\u0639\\u062A\\u0647\\u060C \\u0648\\u064A\\u0643\\u0645\\u0644."
t["In a good way? Then you can tell me why."] = "\\u0628\\u0627\\u0644\\u0645\\u0646\\u064A\\u062D\\u061F \\u0637\\u064A\\u0628 \\u0627\\u062D\\u0643\\u064A\\u0644\\u064A \\u0644\\u064A\\u0634."
t["Insufficient leverage. Rerouting."] = "\\u0645\\u0627 \\u0641\\u064A \\u0645\\u0633\\u0643\\u0629 \\u0643\\u0641\\u0627\\u064A\\u0629. \\u0645\\u0646\\u063A\\u064A\\u0631 \\u0627\\u0644\\u0637\\u0631\\u064A\\u0642."
t["Interesting. I did not expect that turn."] = "\\u062D\\u0644\\u0648. \\u0645\\u0627 \\u0643\\u0646\\u062A \\u0645\\u062A\\u0648\\u0642\\u0639\\u0629 \\u0647\\u0627\\u0644\\u0646\\u0642\\u0644\\u0629."
t["Interesting. I had been doing that the hard way."] = "\\u063A\\u0631\\u064A\\u0628. \\u0643\\u0646\\u062A \\u0639\\u0645 \\u0627\\u0639\\u0645\\u0644\\u0647\\u0627 \\u0628\\u0627\\u0644\\u0637\\u0631\\u064A\\u0642\\u0629 \\u0627\\u0644\\u0635\\u0639\\u0628\\u0629."
t["Interesting. Useless, but interesting."] = "\\u0637\\u0631\\u064A\\u0641\\u0629. \\u0628\\u0644\\u0627 \\u0641\\u0627\\u064A\\u062F\\u0629\\u060C \\u0628\\u0633 \\u0637\\u0631\\u064A\\u0641\\u0629."
t["Interior spacing is bad. Taking it outside."] = "\\u0627\\u0644\\u0645\\u0633\\u0627\\u062D\\u0629 \\u062C\\u0648\\u0627 \\u0639\\u0627\\u0637\\u0644\\u0629. \\u0631\\u062D \\u0637\\u0644\\u0639\\u0647\\u0627 \\u0628\\u0631\\u0627."
t["Into the bag you go."] = "\\u0639\\u0627\\u0644\\u0643\\u064A\\u0633 \\u064A\\u0627 \\u062D\\u0644\\u0648\\u0629."
t["Into the ground. Your turn to fight."] = "\\u0639\\u0627\\u0644\\u0623\\u0631\\u0636. \\u0647\\u0644\\u0623 \\u062F\\u0648\\u0631\\u0643\\u0646 \\u0628\\u0627\\u0644\\u0642\\u062A\\u0627\\u0644."
t["Is it warm in here, or is it me?"] = "\\u0627\\u0644\\u062C\\u0648 \\u062D\\u0627\\u0645\\u064A \\u0647\\u0648\\u0646\\u060C \\u0648\\u0644\\u0627 \\u0623\\u0646\\u0627\\u061F"
t["Is there anyone who needs a hand? I need to move."] = "\\u062D\\u062F\\u0627 \\u0645\\u062D\\u062A\\u0627\\u062C \\u0625\\u064A\\u062F\\u061F \\u0644\\u0627\\u0632\\u0645 \\u0627\\u062A\\u062D\\u0631\\u0643."
t["It died. We plant again. That is the answer."] = "\\u0645\\u0627\\u062A. \\u0645\\u0646\\u0631\\u062C\\u0639 \\u0646\\u0632\\u0631\\u0639. \\u0647\\u0627\\u062F \\u0627\\u0644\\u062C\\u0648\\u0627\\u0628."
t["It feels like people live here, not just hide here."] = "\\u062D\\u0627\\u0633\\u0629 \\u0625\\u0646\\u0647 \\u0627\\u0644\\u0646\\u0627\\u0633 \\u0639\\u0627\\u064A\\u0634\\u0629 \\u0647\\u0648\\u0646\\u060C \\u0645\\u0648 \\u0628\\u0633 \\u0645\\u062E\\u0628\\u0627\\u064A\\u0629."
t["It feels like waiting for a call that never quite comes."] = "\\u062D\\u0627\\u0633\\u0629 \\u062D\\u0627\\u0644\\u064A \\u0646\\u0627\\u0637\\u0631\\u0629 \\u062A\\u0644\\u0641\\u0648\\u0646 \\u0639\\u0645\\u0631\\u0647 \\u0645\\u0627 \\u0628\\u064A\\u062C\\u064A."
t["It grew. Best not to look surprised."] = "\\u0637\\u0644\\u0639. \\u0627\\u0644\\u0623\\u062D\\u0633\\u0646 \\u0645\\u0627 \\u0646\\u0628\\u064A\\u0651\\u0646 \\u0625\\u0646\\u0627 \\u062A\\u0641\\u0627\\u062C\\u0623\\u0646\\u0627."
t["It happened out there. I'm scared. Don't tell them."] = "\\u0635\\u0627\\u0631\\u062A \\u0628\\u0631\\u0627. \\u0623\\u0646\\u0627 \\u062E\\u0627\\u064A\\u0641\\u0629. \\u0644\\u0627 \\u062A\\u062E\\u0628\\u0631\\u0647\\u0646."
t["It hurts. It hurts all the way down in my bones."] = "\\u0639\\u0645 \\u062A\\u0648\\u062C\\u0639\\u0646\\u064A. \\u0639\\u0645 \\u062A\\u0648\\u062C\\u0639\\u0646\\u064A \\u0644\\u062C\\u0648\\u0627 \\u0639\\u0636\\u0627\\u0645\\u064A."
t["It is strange hearing someone speak to the whole county."] = "\\u063A\\u0631\\u064A\\u0628 \\u062A\\u0633\\u0645\\u0639 \\u062D\\u062F\\u0627 \\u0639\\u0645 \\u064A\\u062D\\u0643\\u064A \\u0644\\u0644\\u0645\\u0642\\u0627\\u0637\\u0639\\u0629 \\u0643\\u0644\\u0647\\u0627."
t["It is too quiet without %1 here."] = "\\u0628\\u0644\\u0627 %1 \\u0627\\u0644\\u0645\\u062D\\u0644 \\u0633\\u0627\\u0643\\u062A \\u0643\\u062A\\u064A\\u0631."
t["It isn't anyone's fault. I just need to be alone."] = "\\u0645\\u0648 \\u063A\\u0644\\u0637\\u0629 \\u062D\\u062F\\u0627. \\u0628\\u0633 \\u0628\\u062F\\u064A \\u0643\\u0648\\u0646 \\u0644\\u062D\\u0627\\u0644\\u064A."
t["It isn't foolish if the story helped someone through the night."] = "\\u0645\\u0648 \\u0633\\u062E\\u064A\\u0641 \\u0625\\u0630\\u0627 \\u0627\\u0644\\u0642\\u0635\\u0629 \\u0633\\u0627\\u0639\\u062F\\u062A \\u062D\\u062F\\u0627 \\u064A\\u0645\\u0631\\u0642 \\u0627\\u0644\\u0644\\u064A\\u0644."
t["It keeps getting back up!"] = "\\u0643\\u0644 \\u0645\\u0627 \\u0648\\u0642\\u0639 \\u0628\\u064A\\u0642\\u0648\\u0645!"
t["It matters to me. That's why I'm taking my time with it."] = "\\u0628\\u062A\\u0641\\u0631\\u0642 \\u0645\\u0639\\u064A. \\u0645\\u0634\\u0627\\u0646 \\u0647\\u064A\\u0643 \\u0639\\u0645 \\u0622\\u062E\\u062F \\u0648\\u0642\\u062A\\u064A \\u0641\\u064A\\u0647\\u0627."
t["It went down like it was tired. Maybe it was."] = "\\u0648\\u0642\\u0639 \\u0643\\u0623\\u0646\\u0647 \\u062A\\u0639\\u0628\\u0627\\u0646. \\u064A\\u0645\\u0643\\u0646 \\u0643\\u0627\\u0646."
t["It won't be following us."] = "\\u0647\\u0627\\u062F \\u0645\\u0627 \\u0639\\u0627\\u062F \\u0628\\u064A\\u0644\\u062D\\u0642\\u0646\\u0627."
t["It'll move on. What it drags behind it won't."] = "\\u0631\\u062D \\u062A\\u0631\\u0648\\u062D. \\u0628\\u0633 \\u0627\\u0644\\u0644\\u064A \\u062C\\u0631\\u0651\\u062A\\u0647 \\u0648\\u0631\\u0627\\u0647\\u0627 \\u0645\\u0648 \\u0631\\u062D \\u064A\\u0631\\u0648\\u062D."
t["It'll ring until the battery dies. We shouldn't be here when it does."] = "\\u0631\\u062D \\u064A\\u0636\\u0644 \\u064A\\u0632\\u0645\\u0631 \\u0644\\u062A\\u0645\\u0648\\u062A \\u0627\\u0644\\u0628\\u0637\\u0627\\u0631\\u064A\\u0629. \\u0648\\u0644\\u0627\\u0632\\u0645 \\u0645\\u0627 \\u0646\\u0643\\u0648\\u0646 \\u0647\\u0648\\u0646 \\u0648\\u0642\\u062A\\u0647\\u0627."
t["It's a bite. I checked twice. It's a bite."] = "\\u0639\\u0636\\u0629. \\u0634\\u064A\\u0651\\u0643\\u062A \\u0645\\u0631\\u062A\\u064A\\u0646. \\u0639\\u0636\\u0629."
t["It's down!"] = "\\u0648\\u0642\\u0639!"
t["It's down. Check around us!"] = "\\u0648\\u0642\\u0639. \\u0634\\u0648\\u0641 \\u062D\\u0648\\u0627\\u0644\\u064A\\u0646\\u0627!"
t["It's down. Is everyone all right?"] = "\\u0648\\u0642\\u0639. \\u0627\\u0644\\u0643\\u0644 \\u0645\\u0646\\u064A\\u062D?"
t["It's easier hearing another person breathe. Especially you."] = "\\u0623\\u0647\\u0648\\u0646 \\u0644\\u0645\\u0627 \\u0627\\u0633\\u0645\\u0639 \\u062D\\u062F\\u0627 \\u0639\\u0645 \\u064A\\u062A\\u0646\\u0641\\u0633. \\u062E\\u0635\\u0648\\u0635\\u0627\\u064B \\u0625\\u0646\\u062A."
t["It's getting dark. Let me know if anyone needs anything."] = "\\u0639\\u0645 \\u062A\\u0639\\u062A\\u0645. \\u0625\\u0630\\u0627 \\u062D\\u062F\\u0627 \\u0628\\u062F\\u0648 \\u0634\\u064A\\u060C \\u064A\\u0642\\u0644\\u064A."
t["It's getting dark. Let's make sure everyone's back."] = "\\u0639\\u0645 \\u062A\\u0639\\u062A\\u0645. \\u062E\\u0644\\u064A\\u0646\\u0627 \\u0646\\u062A\\u0623\\u0643\\u062F \\u0627\\u0644\\u0643\\u0644 \\u0631\\u062C\\u0639."
t["It's good to be useful without being used."] = "\\u062D\\u0644\\u0648 \\u0643\\u0648\\u0646 \\u0645\\u0641\\u064A\\u062F\\u0629 \\u0628\\u0644\\u0627 \\u0645\\u0627 \\u062D\\u062F\\u0627 \\u064A\\u0633\\u062A\\u063A\\u0644\\u0646\\u064A."
t["It's good to see you alive. We still need some distance."] = "\\u0645\\u0646\\u064A\\u062D \\u0634\\u0648\\u0641\\u0643 \\u0639\\u0627\\u064A\\u0634. \\u0628\\u0633 \\u0644\\u0633\\u0627 \\u0628\\u062F\\u0646\\u0627 \\u0645\\u0633\\u0627\\u0641\\u0629."
t["It's my decision. I want it that way."] = "\\u0647\\u0627\\u062F \\u0642\\u0631\\u0627\\u0631\\u064A. \\u0648\\u0628\\u062F\\u064A \\u064A\\u0627\\u0647\\u0627 \\u0647\\u064A\\u0643."
t["It's not about size. It's all about speed."] = "\\u0645\\u0648 \\u0639\\u0627\\u0644\\u062D\\u062C\\u0645. \\u0643\\u0644\\u0647 \\u0639\\u0627\\u0644\\u0633\\u0631\\u0639\\u0629."
t["It's strange how a table makes a small meal feel less lonely."] = "\\u063A\\u0631\\u064A\\u0628 \\u0643\\u064A\\u0641 \\u0627\\u0644\\u0637\\u0627\\u0648\\u0644\\u0629 \\u0628\\u062A\\u062E\\u0644\\u064A \\u0627\\u0644\\u0623\\u0643\\u0644\\u0629 \\u0627\\u0644\\u0635\\u063A\\u064A\\u0631\\u0629 \\u0623\\u0642\\u0644 \\u0648\\u062D\\u062F\\u0629."
t["It's too tight in here. I don't like this at all."] = "\\u0636\\u064A\\u0642 \\u0643\\u062A\\u064A\\u0631 \\u0647\\u0648\\u0646. \\u0645\\u0648 \\u0639\\u0627\\u062C\\u0628\\u0646\\u064A \\u0623\\u0628\\u062F\\u0627\\u064B."
t["It's wired and ready."] = "\\u0648\\u0635\\u0644\\u062A \\u0627\\u0644\\u0634\\u0631\\u0627\\u064A\\u0637 \\u0648\\u062C\\u0627\\u0647\\u0632\\u0629."
t["It's yours. Put it to good use."] = "\\u0635\\u0627\\u0631 \\u0625\\u0644\\u0643. \\u0627\\u0633\\u062A\\u0639\\u0645\\u0644\\u0647 \\u0645\\u0646\\u064A\\u062D."
t["Jay's Chicken. Finger-licking and then some."] = "\\u062F\\u062C\\u0627\\u062C \\u062C\\u0627\\u064A. \\u0628\\u062A\\u0644\\u062D\\u0633 \\u0623\\u0635\\u0627\\u0628\\u064A\\u0639\\u0643 \\u0648\\u0632\\u064A\\u0627\\u062F\\u0629."
t["Jesus Christ, please don't. I'm barely holding it together."] = "\\u064A\\u0627 \\u064A\\u0633\\u0648\\u0639 \\u0627\\u0644\\u0645\\u0633\\u064A\\u062D\\u060C \\u062F\\u062E\\u064A\\u0644\\u0643 \\u0644\\u0623. \\u064A\\u0627 \\u062F\\u0648\\u0628 \\u0645\\u0627\\u0633\\u0643\\u0629 \\u062D\\u0627\\u0644\\u064A."
t["Jukebox is out. Small mercies."] = "\\u0627\\u0644\\u062C\\u0648\\u0643\\u0628\\u0648\\u0643\\u0633 \\u0639\\u0637\\u0644\\u0627\\u0646. \\u0646\\u0639\\u0645\\u0629 \\u0635\\u063A\\u064A\\u0631\\u0629."
t["Junk catch. Clear the hook and try again."] = "\\u0635\\u064A\\u062F\\u0629 \\u062E\\u0631\\u062F\\u0629. \\u0628\\u0646\\u0636\\u0641 \\u0627\\u0644\\u0635\\u0646\\u0627\\u0631\\u0629 \\u0648\\u0628\\u062C\\u0631\\u0628 \\u0643\\u0645\\u0627\\u0646 \\u0645\\u0631\\u0629."
t["Just a few minutes to feel human again."] = "\\u0643\\u0645 \\u062F\\u0642\\u064A\\u0642\\u0629 \\u0628\\u0633 \\u0644\\u0623\\u062D\\u0633 \\u062D\\u0627\\u0644\\u064A \\u0628\\u0646\\u064A \\u0622\\u062F\\u0645."
t["Just a passing notion. I'm not charging it rent."] = "\\u062E\\u0627\\u0637\\u0631\\u0629 \\u0639\\u0627\\u0628\\u0631\\u0629. \\u0645\\u0648 \\u0637\\u0627\\u0644\\u0628\\u0629 \\u0645\\u0646\\u0647\\u0627 \\u0623\\u062C\\u0627\\u0631."
t["Just a scratch. Hold still anyway."] = "\\u062E\\u062F\\u0634 \\u0648\\u0628\\u0633. \\u062B\\u0628\\u062A \\u0628\\u0631\\u0636\\u0648."
t["Just die already!"] = "\\u0645\\u0648\\u062A \\u0628\\u0642\\u0649!"
t["Just don't pick the only patch of poison ivy."] = "\\u0628\\u0633 \\u0644\\u0627 \\u062A\\u062E\\u062A\\u0627\\u0631 \\u0627\\u0644\\u0631\\u0642\\u0639\\u0629 \\u0627\\u0644\\u0648\\u062D\\u064A\\u062F\\u0629 \\u0627\\u0644\\u0644\\u064A \\u0641\\u064A\\u0647\\u0627 \\u0644\\u0628\\u0644\\u0627\\u0628 \\u0645\\u0633\\u0645\\u0648\\u0645."
